PROBLEMS=[]
def add(difficulty,title,task,sql,topics,explain='',company=None,ordered=False):
 PROBLEMS.append(dict(difficulty=difficulty,title=title,task=task,sql=sql,topics=topics.split('|'),explain=explain,company=company,ordered=ordered))
def E(*args,**kw):add('Easy',*args,**kw)
def M(*args,**kw):add('Medium',*args,**kw)
def H(*args,**kw):add('Hard',*args,**kw)
# 40 independently authored fundamentals.
E('India’s New Customers','Return id and name for customers in IN who signed up during January 2025.','SELECT id,name FROM customers WHERE country=\'IN\' AND signup_date>=\'2025-01-01\' AND signup_date<\'2025-02-01\'','SELECT and WHERE',company='Flipkart')
E('Completed Sales Total','Return completed_revenue, the sum of completed order amounts. Use 0 for no qualifying orders.',"SELECT COALESCE(SUM(amount),0) AS completed_revenue FROM orders WHERE status='completed'",'Aggregate functions|NULL handling')
E('Order Status Breakdown','Return status, order_count and total_amount for each status present in orders.','SELECT status,COUNT(*) AS order_count,SUM(amount) AS total_amount FROM orders GROUP BY status','GROUP BY')
E('Returning Shoppers','Return customer_id and order_count for customers with at least two completed orders.',"SELECT customer_id,COUNT(*) AS order_count FROM orders WHERE status='completed' GROUP BY customer_id HAVING COUNT(*)>=2",'GROUP BY|HAVING')
E('Unattributed Signups','Return id and name of customers whose acquisition channel is missing.','SELECT id,name FROM customers WHERE channel IS NULL','NULL handling')
E('Catalogue Price Range','Return category, minimum_price and maximum_price for every product category.','SELECT category,MIN(price) AS minimum_price,MAX(price) AS maximum_price FROM products GROUP BY category','Aggregate functions')
E('Cheapest Five Products','Return id, name and price for the five cheapest products; break price ties by id. Sort by price then id.','SELECT id,name,price FROM products ORDER BY price,id LIMIT 5','ORDER BY',ordered=True)
E('Discounted Line Items','Return order_id and product_id for each line whose unit_price is below the current product price. Keep duplicate lines.','SELECT i.order_id,i.product_id FROM items i JOIN products p ON p.id=i.product_id WHERE i.unit_price<p.price','INNER joins')
E('Products Never Ordered','Return product id and name for products absent from items, regardless of order status.','SELECT p.id,p.name FROM products p LEFT JOIN items i ON i.product_id=p.id WHERE i.product_id IS NULL','LEFT joins|Anti-joins')
E('Payment Attempts per Order','Return order_id, attempt_count and successful_count for each order with a payment attempt.',"SELECT order_id,COUNT(*) AS attempt_count,SUM(CASE WHEN status='success' THEN 1 ELSE 0 END) AS successful_count FROM payments GROUP BY order_id",'CASE WHEN|Conditional aggregation',company='PayPal')
E('Successful Payment Volume','Return paid_amount: the sum of successful payments. Use 0 if none.',"SELECT COALESCE(SUM(amount),0) AS paid_amount FROM payments WHERE status='success'",'Aggregate functions',company='PhonePe')
E('Customers with No Orders','Return customer id and name for customers who have never placed any order.','SELECT c.id,c.name FROM customers c WHERE NOT EXISTS(SELECT 1 FROM orders o WHERE o.customer_id=c.id)','NOT EXISTS')
E('Countries in the Community','Return each distinct country represented by a customer.','SELECT DISTINCT country FROM customers','SELECT and WHERE')
E('Acquisition Mix','Return channel and customer_count. Group missing channels under the literal Unknown.',"SELECT COALESCE(channel,'Unknown') AS channel,COUNT(*) AS customer_count FROM customers GROUP BY COALESCE(channel,'Unknown')",'Data cleaning|GROUP BY')
E('Above-Catalogue Average','Return id and name for products priced strictly above the average price of all products.','SELECT id,name FROM products WHERE price>(SELECT AVG(price) FROM products)','Subqueries')
E('Undelivered Parcels','Return order_id and courier_id for deliveries without a delivered_at timestamp.','SELECT order_id,courier_id FROM deliveries WHERE delivered_at IS NULL','NULL handling',company='Swiggy')
E('Late Delivery List','Return order_id and courier_id for deliveries completed after promised_at.','SELECT order_id,courier_id FROM deliveries WHERE delivered_at>promised_at','SELECT and WHERE',company='Zomato')
E('Open High Priority Tickets','Return id and customer_id for unresolved high priority tickets.',"SELECT id,customer_id FROM tickets WHERE resolved_at IS NULL AND priority='high'",'SELECT and WHERE',company='Salesforce')
E('Support Backlog','Return priority and open_count for each priority with unresolved tickets.','SELECT priority,COUNT(*) AS open_count FROM tickets WHERE resolved_at IS NULL GROUP BY priority','GROUP BY')
E('Headcount by Department','Return department, headcount and known_salaries. Count all employees for headcount but only non-NULL salaries for known_salaries.','SELECT department,COUNT(*) AS headcount,COUNT(salary) AS known_salaries FROM employees GROUP BY department','Aggregate functions|NULL handling',company='Accenture')
E('Departments with Large Payroll','Return department and payroll for departments whose known salaries total more than 150000.','SELECT department,SUM(salary) AS payroll FROM employees GROUP BY department HAVING SUM(salary)>150000','HAVING',company='Deloitte')
E('Manager Directory','Return employee_name and manager_name for employees with a manager present in employees.','SELECT e.name AS employee_name,m.name AS manager_name FROM employees e JOIN employees m ON e.manager_id=m.id','Self joins')
E('Top Level Leaders','Return id and name of employees with no manager.','SELECT id,name FROM employees WHERE manager_id IS NULL','NULL handling')
E('Active Subscription Records','Return id, customer_id and plan for subscription records with no end_date.','SELECT id,customer_id,plan FROM subscriptions WHERE end_date IS NULL','SELECT and WHERE',company='Netflix')
E('Plan Pricing Average','Return plan and average_fee rounded to two decimals for each plan represented by a subscription record.','SELECT plan,ROUND(AVG(monthly_fee),2) AS average_fee FROM subscriptions GROUP BY plan','Aggregate functions')
E('Refunded Orders','Return order_id and refunded_amount for each order with one or more refunds.','SELECT order_id,SUM(amount) AS refunded_amount FROM refunds GROUP BY order_id','GROUP BY')
E('Event Audience by Device','Return device and active_customers: distinct customers with at least one event on that device.','SELECT device,COUNT(DISTINCT customer_id) AS active_customers FROM events GROUP BY device','Aggregate functions',company='Google')
E('Purchase Event Count','Return purchases, the number of event rows whose event_type is purchase.',"SELECT COUNT(*) AS purchases FROM events WHERE event_type='purchase'",'SELECT and WHERE')
E('Ad Click-Through Rate','For every channel in ad_spend, return channel and ctr_pct = 100*total clicks/total impressions, rounded to 2 decimals. Return NULL if impressions total 0.','SELECT channel,ROUND(100.0*SUM(clicks)/NULLIF(SUM(impressions),0),2) AS ctr_pct FROM ad_spend GROUP BY channel','NULL handling|Business analytics',company='Meta')
E('Account Ownership','Return account_id, customer_name and country for each account whose owner is present in customers.','SELECT a.id AS account_id,c.name AS customer_name,c.country FROM accounts a JOIN customers c ON c.id=a.customer_id','INNER joins',company='JPMorgan Chase')
E('Debit Merchant Volume','Return merchant and debit_amount for non-NULL merchants on debit transactions.',"SELECT merchant,SUM(amount) AS debit_amount FROM ledger WHERE kind='debit' AND merchant IS NOT NULL GROUP BY merchant",'GROUP BY',company='Goldman Sachs')
E('High Rated Products','Return product_id and average_stars for products with at least 2 ratings and average stars of at least 4; round the average to 2 decimals.','SELECT product_id,ROUND(AVG(stars),2) AS average_stars FROM ratings GROUP BY product_id HAVING COUNT(*)>=2 AND AVG(stars)>=4','HAVING')
E('Zero Inventory Days','Return product_id and day for stock snapshots with units equal to zero.','SELECT product_id,day FROM stock WHERE units=0','SELECT and WHERE',company='Walmart')
E('Hours by Project','Return project_id and total_hours for each project with assignment records.','SELECT project_id,SUM(hours) AS total_hours FROM assignments GROUP BY project_id','GROUP BY')
E('Unstaffed Projects','Return project id and name when no assignment exists.','SELECT p.id,p.name FROM projects p WHERE NOT EXISTS(SELECT 1 FROM assignments a WHERE a.project_id=p.id)','Anti-joins')
E('Genre Watch Time','Return genre and watched_minutes, summing minutes across all watch records.','SELECT genre,SUM(minutes) AS watched_minutes FROM watches GROUP BY genre','GROUP BY',company='Netflix')
E('Distinct Titles per Viewer','Return customer_id and title_count for each viewer, counting distinct titles.','SELECT customer_id,COUNT(DISTINCT title) AS title_count FROM watches GROUP BY customer_id','Aggregate functions')
E('Low Value Order Labels','For every order return id and value_band. Use zero for amount=0, small for 0<amount<100, and standard otherwise.',"SELECT id,CASE WHEN amount=0 THEN 'zero' WHEN amount<100 THEN 'small' ELSE 'standard' END AS value_band FROM orders",'CASE WHEN')
E('Repeat Product Ratings','Return customer_id, product_id and rating_count for customer-product pairs with more than one rating.','SELECT customer_id,product_id,COUNT(*) AS rating_count FROM ratings GROUP BY customer_id,product_id HAVING COUNT(*)>1','Duplicate detection')
E('Recent Refund Window','Return id, order_id and amount for refunds from February 1 through February 28, 2025, inclusive.',"SELECT id,order_id,amount FROM refunds WHERE refunded_at>='2025-02-01' AND refunded_at<'2025-03-01'",'Date functions')
# 110 distinct intermediate business and query patterns.
M('Customer Lifetime Revenue','Return every customer id and completed_revenue, including 0 for customers with no completed orders.',"SELECT c.id,COALESCE(SUM(CASE WHEN o.status='completed' THEN o.amount ELSE 0 END),0) AS completed_revenue FROM customers c LEFT JOIN orders o ON o.customer_id=c.id GROUP BY c.id",'LEFT joins|Conditional aggregation')
M('First Completed Purchase','Return customer_id, first_order_id and order_date for each customer with a completed order. Break same-date ties by lower order id.',"WITH r AS(SELECT customer_id,id,order_date,ROW_NUMBER() OVER(PARTITION BY customer_id ORDER BY order_date,id) AS rn FROM orders WHERE status='completed') SELECT customer_id,id AS first_order_id,order_date FROM r WHERE rn=1",'ROW_NUMBER|First and last events')
M('Latest Customer Event','Return customer_id, event_type and event_time for the latest event per customer; break time ties by higher event id.','WITH r AS(SELECT *,ROW_NUMBER() OVER(PARTITION BY customer_id ORDER BY event_time DESC,id DESC) AS rn FROM events) SELECT customer_id,event_type,event_time FROM r WHERE rn=1','ROW_NUMBER|First and last events')
M('Second Distinct Salary','Return department and second_salary for departments having a second distinct non-NULL salary, descending.','WITH r AS(SELECT department,salary,DENSE_RANK() OVER(PARTITION BY department ORDER BY salary DESC) AS dr FROM employees WHERE salary IS NOT NULL) SELECT DISTINCT department,salary AS second_salary FROM r WHERE dr=2','DENSE_RANK')
M('Three Highest Paid Employees','Return department, id and salary for up to three employees per department with non-NULL salary. Sort salary descending and break ties by id to select exactly three.','WITH r AS(SELECT *,ROW_NUMBER() OVER(PARTITION BY department ORDER BY salary DESC,id) AS rn FROM employees WHERE salary IS NOT NULL) SELECT department,id,salary FROM r WHERE rn<=3','Top N per group|ROW_NUMBER')
M('Outearning Your Manager','Return employee_id, employee_salary and manager_salary for employees whose salary exceeds their manager’s.','SELECT e.id AS employee_id,e.salary AS employee_salary,m.salary AS manager_salary FROM employees e JOIN employees m ON e.manager_id=m.id WHERE e.salary>m.salary','Self joins')
M('Department Salary Benchmark','Return employee id and salary_gap = employee salary minus department average salary, rounded to 2 decimals. Exclude NULL salaries.','SELECT id,ROUND(salary-AVG(salary) OVER(PARTITION BY department),2) AS salary_gap FROM employees WHERE salary IS NOT NULL','Window functions')
M('Payroll Percentage','Return id and payroll_pct, each known salary as a percentage of its department’s known payroll, rounded to 2 decimals; NULL if payroll is zero.','SELECT id,ROUND(100.0*salary/NULLIF(SUM(salary) OVER(PARTITION BY department),0),2) AS payroll_pct FROM employees WHERE salary IS NOT NULL','Window functions|Business analytics')
M('Daily Revenue Ledger','Return order_date, revenue and running_revenue for completed orders, aggregating per day before the running sum.',"WITH d AS(SELECT order_date,SUM(amount) AS revenue FROM orders WHERE status='completed' GROUP BY order_date) SELECT order_date,revenue,SUM(revenue) OVER(ORDER BY order_date ROWS UNBOUNDED PRECEDING) AS running_revenue FROM d",'Running totals|CTEs')
M('Previous Purchase Gap','For each completed order return id, customer_id and days_since_previous. Order each customer’s purchases by date then id; first purchase gap is NULL.',"WITH r AS(SELECT id,customer_id,order_date,LAG(order_date) OVER(PARTITION BY customer_id ORDER BY order_date,id) AS prev FROM orders WHERE status='completed') SELECT id,customer_id,DIFFDAY(order_date,prev) AS days_since_previous FROM r",'LAG and LEAD|Date functions')
M('Next Event Type','Return id, customer_id and next_type, the next event type per customer ordered by event_time then id. Last events have NULL next_type.','SELECT id,customer_id,LEAD(event_type) OVER(PARTITION BY customer_id ORDER BY event_time,id) AS next_type FROM events','LAG and LEAD')
M('Three Observation Revenue Average','Aggregate completed revenue by order_date. Return order_date and rolling_average over the current and previous two observed dates, rounded to 2 decimals; missing dates are not added.',"WITH d AS(SELECT order_date,SUM(amount) AS revenue FROM orders WHERE status='completed' GROUP BY order_date) SELECT order_date,ROUND(AVG(revenue) OVER(ORDER BY order_date ROWS BETWEEN 2 PRECEDING AND CURRENT ROW),2) AS rolling_average FROM d",'Rolling averages|Window frames')
M('Monthly Revenue Growth','Return month and growth_pct versus the previous observed month for completed revenue. First month or zero prior revenue gives NULL; round to 2 decimals.',"WITH m AS(SELECT MONTHKEY(order_date) AS month,SUM(amount) AS revenue FROM orders WHERE status='completed' GROUP BY MONTHKEY(order_date)),r AS(SELECT *,LAG(revenue) OVER(ORDER BY month) AS previous FROM m) SELECT month,ROUND(100.0*(revenue-previous)/NULLIF(previous,0),2) AS growth_pct FROM r",'LAG and LEAD|Revenue analytics')
M('Country Revenue Leaders','Return country, customer_id and revenue for customers with the highest completed revenue within their country. Include ties; exclude customers with no completed orders.',"WITH r AS(SELECT c.country,c.id AS customer_id,SUM(o.amount) AS revenue FROM customers c JOIN orders o ON o.customer_id=c.id WHERE o.status='completed' GROUP BY c.country,c.id),ranked AS(SELECT *,DENSE_RANK() OVER(PARTITION BY country ORDER BY revenue DESC) AS dr FROM r) SELECT country,customer_id,revenue FROM ranked WHERE dr=1",'DENSE_RANK|Top N per group')
M('Category Sales Contribution','Return category and revenue_pct from completed order line revenue, rounded to 2 decimals. Category totals are based on quantity*unit_price, not order.amount.',"WITH c AS(SELECT p.category,SUM(i.quantity*i.unit_price) AS revenue FROM items i JOIN products p ON p.id=i.product_id JOIN orders o ON o.id=i.order_id WHERE o.status='completed' GROUP BY p.category) SELECT category,ROUND(100.0*revenue/NULLIF(SUM(revenue) OVER(),0),2) AS revenue_pct FROM c",'Complex joins|Window functions')
M('Basket Product Count','Return completed order id, distinct_products and total_units. Include completed orders with no lines as zeros.',"SELECT o.id,COUNT(DISTINCT i.product_id) AS distinct_products,COALESCE(SUM(i.quantity),0) AS total_units FROM orders o LEFT JOIN items i ON i.order_id=o.id WHERE o.status='completed' GROUP BY o.id",'LEFT joins|Aggregate functions')
M('Unpaid Completed Orders','Return id and outstanding_amount for completed orders whose successful payments sum to less than order.amount. Missing payments count as zero.',"WITH p AS(SELECT order_id,SUM(amount) AS paid FROM payments WHERE status='success' GROUP BY order_id) SELECT o.id,o.amount-COALESCE(p.paid,0) AS outstanding_amount FROM orders o LEFT JOIN p ON p.order_id=o.id WHERE o.status='completed' AND COALESCE(p.paid,0)<o.amount",'CTEs|LEFT joins')
M('Overpaid Orders','Return order id and excess_payment where successful payment total is strictly greater than order.amount.','SELECT o.id,SUM(p.amount)-o.amount AS excess_payment FROM orders o JOIN payments p ON p.order_id=o.id WHERE p.status=\'success\' GROUP BY o.id,o.amount HAVING SUM(p.amount)>o.amount','HAVING|INNER joins')
M('Net Collected Cash','Return every order id and net_cash = successful payments minus all refunds. Missing totals are zero; aggregate independently to avoid fan-out.',"WITH p AS(SELECT order_id,SUM(amount) AS paid FROM payments WHERE status='success' GROUP BY order_id),r AS(SELECT order_id,SUM(amount) AS refunded FROM refunds GROUP BY order_id) SELECT o.id,COALESCE(p.paid,0)-COALESCE(r.refunded,0) AS net_cash FROM orders o LEFT JOIN p ON p.order_id=o.id LEFT JOIN r ON r.order_id=o.id",'Complex joins|CTEs')
M('Payment Recovery','Return order_id where at least one failed payment occurred before a successful payment. Compare timestamp, then id for equal timestamps.',"SELECT DISTINCT f.order_id FROM payments f JOIN payments s ON f.order_id=s.order_id WHERE f.status='failed' AND s.status='success' AND (s.paid_at>f.paid_at OR (s.paid_at=f.paid_at AND s.id>f.id))",'Self joins|EXISTS')
M('Final Payment Outcome','Return order_id and status for the most recent payment attempt per order, breaking timestamp ties by larger id.','WITH r AS(SELECT *,ROW_NUMBER() OVER(PARTITION BY order_id ORDER BY paid_at DESC,id DESC) AS rn FROM payments) SELECT order_id,status FROM r WHERE rn=1','ROW_NUMBER')
M('Repeat Refund Orders','Return order_id and refund_count for orders refunded more than once; additionally return refund_total.','SELECT order_id,COUNT(*) AS refund_count,SUM(amount) AS refund_total FROM refunds GROUP BY order_id HAVING COUNT(*)>1','HAVING|Business analytics')
M('Revenue Without Refunded Orders','Return revenue from completed orders that have no refund records. Use zero for no qualifying orders.',"SELECT COALESCE(SUM(o.amount),0) AS revenue FROM orders o WHERE o.status='completed' AND NOT EXISTS(SELECT 1 FROM refunds r WHERE r.order_id=o.id)",'Anti-joins|Correlated subqueries')
M('All Status Customer Pivot','Return every customer id plus completed_count, cancelled_count and other_count. Other includes refunded and pending orders, but not an absent order.',"SELECT c.id,SUM(CASE WHEN o.status='completed' THEN 1 ELSE 0 END) AS completed_count,SUM(CASE WHEN o.status='cancelled' THEN 1 ELSE 0 END) AS cancelled_count,SUM(CASE WHEN o.id IS NOT NULL AND o.status NOT IN ('completed','cancelled') THEN 1 ELSE 0 END) AS other_count FROM customers c LEFT JOIN orders o ON o.customer_id=c.id GROUP BY c.id",'Pivoting|Conditional aggregation')
M('Cross Category Shoppers','Return customer_id for customers who bought products from at least two categories in completed orders.',"SELECT o.customer_id FROM orders o JOIN items i ON i.order_id=o.id JOIN products p ON p.id=i.product_id WHERE o.status='completed' GROUP BY o.customer_id HAVING COUNT(DISTINCT p.category)>=2",'Complex joins|HAVING')
M('Electronics Only Customers','Return customers with completed order lines in Electronics and no completed order lines in another category.',"SELECT o.customer_id FROM orders o JOIN items i ON i.order_id=o.id JOIN products p ON p.id=i.product_id WHERE o.status='completed' GROUP BY o.customer_id HAVING COUNT(*)>0 AND SUM(CASE WHEN p.category<>'Electronics' THEN 1 ELSE 0 END)=0",'Conditional aggregation')
M('Customers without Successful Payment','Return customer id for customers with at least one order but no successful payment across any of their orders.',"SELECT c.id FROM customers c WHERE EXISTS(SELECT 1 FROM orders o WHERE o.customer_id=c.id) AND NOT EXISTS(SELECT 1 FROM orders o JOIN payments p ON p.order_id=o.id WHERE o.customer_id=c.id AND p.status='success')",'EXISTS|NOT EXISTS')
M('Registration to Purchase','Return customer_id and days_to_purchase between signup_date and their first completed order_date.',"SELECT c.id AS customer_id,DIFFDAY(MIN(o.order_date),c.signup_date) AS days_to_purchase FROM customers c JOIN orders o ON o.customer_id=c.id AND o.status='completed' GROUP BY c.id,c.signup_date",'Date functions|Aggregate functions')
M('Same Day Conversion','Return signup_date, signup_count and converted_count for each signup date. A customer converts if any completed order is on their signup date.',"SELECT c.signup_date,COUNT(*) AS signup_count,SUM(CASE WHEN EXISTS(SELECT 1 FROM orders o WHERE o.customer_id=c.id AND o.status='completed' AND o.order_date=c.signup_date) THEN 1 ELSE 0 END) AS converted_count FROM customers c GROUP BY c.signup_date",'Conversion rates|EXISTS')
M('Referral Revenue','Return referrer_id and referred_revenue from completed orders by directly referred customers. Include referrers with referrals but no completed revenue as 0.',"SELECT c.referrer_id,COALESCE(SUM(CASE WHEN o.status='completed' THEN o.amount ELSE 0 END),0) AS referred_revenue FROM customers c LEFT JOIN orders o ON o.customer_id=c.id WHERE c.referrer_id IS NOT NULL GROUP BY c.referrer_id",'LEFT joins|Revenue analytics')
M('Inactive Thirty-Day Buyers','As of 2025-03-15, return customer_id and last_order for customers whose latest completed order on or before that date was more than 30 days earlier.',"SELECT customer_id,MAX(order_date) AS last_order FROM orders WHERE status='completed' AND order_date<='2025-03-15' GROUP BY customer_id HAVING DIFFDAY('2025-03-15',MAX(order_date))>30",'Churn analysis|Date functions')
M('First versus Repeat Revenue','For completed orders, classify each customer’s first order as new and later orders as repeat, breaking date ties by id. Return purchase_type and revenue.',"WITH r AS(SELECT amount,ROW_NUMBER() OVER(PARTITION BY customer_id ORDER BY order_date,id) AS rn FROM orders WHERE status='completed') SELECT CASE WHEN rn=1 THEN 'new' ELSE 'repeat' END AS purchase_type,SUM(amount) AS revenue FROM r GROUP BY CASE WHEN rn=1 THEN 'new' ELSE 'repeat' END",'ROW_NUMBER|Revenue analytics')
M('Quarter One Customer Segments','Using completed orders in Jan-Mar 2025, return every customer id and segment: VIP for revenue >=500, repeat for at least two orders otherwise, new for one order, inactive for zero.',"SELECT c.id,CASE WHEN COALESCE(SUM(o.amount),0)>=500 THEN 'VIP' WHEN COUNT(o.id)>=2 THEN 'repeat' WHEN COUNT(o.id)=1 THEN 'new' ELSE 'inactive' END AS segment FROM customers c LEFT JOIN orders o ON o.customer_id=c.id AND o.status='completed' AND o.order_date>='2025-01-01' AND o.order_date<'2025-04-01' GROUP BY c.id",'Customer segmentation|CASE WHEN')
M('Average Basket by Acquisition','Return channel and average_order_amount across completed orders, rounded to 2 decimals. Treat NULL channels as Unknown.',"SELECT COALESCE(c.channel,'Unknown') AS channel,ROUND(AVG(o.amount),2) AS average_order_amount FROM customers c JOIN orders o ON o.customer_id=c.id WHERE o.status='completed' GROUP BY COALESCE(c.channel,'Unknown')",'Business analytics|INNER joins')
M('Order Amount Reconciliation','Return order id, amount and line_total where the stored amount differs from summed line revenue. Include orders without lines with line_total zero.','SELECT o.id,o.amount,COALESCE(SUM(i.quantity*i.unit_price),0) AS line_total FROM orders o LEFT JOIN items i ON i.order_id=o.id GROUP BY o.id,o.amount HAVING o.amount<>COALESCE(SUM(i.quantity*i.unit_price),0)','HAVING|Data cleaning')
M('Product Revenue Rank','Return product_id, revenue and revenue_rank among products with completed sales. Use RANK, descending revenue; keep gaps after ties.',"WITH r AS(SELECT i.product_id,SUM(i.quantity*i.unit_price) AS revenue FROM items i JOIN orders o ON o.id=i.order_id WHERE o.status='completed' GROUP BY i.product_id) SELECT product_id,revenue,RANK() OVER(ORDER BY revenue DESC) AS revenue_rank FROM r",'RANK')
M('Most Popular Category by Units','Return category and units for every category tied for highest completed-sale unit volume.',"WITH c AS(SELECT p.category,SUM(i.quantity) AS units FROM products p JOIN items i ON i.product_id=p.id JOIN orders o ON o.id=i.order_id WHERE o.status='completed' GROUP BY p.category) SELECT category,units FROM c WHERE units=(SELECT MAX(units) FROM c)",'CTEs|Subqueries')
M('Orders Above Customer Average','Return id, customer_id and amount for completed orders above that customer’s average completed order amount.',"SELECT o.id,o.customer_id,o.amount FROM orders o WHERE o.status='completed' AND o.amount>(SELECT AVG(x.amount) FROM orders x WHERE x.customer_id=o.customer_id AND x.status='completed')",'Correlated subqueries')
M('Latest Rating per Customer Product','Return customer_id, product_id and stars from the latest rating for each pair; break date ties by largest id.','WITH r AS(SELECT *,ROW_NUMBER() OVER(PARTITION BY customer_id,product_id ORDER BY review_date DESC,id DESC) AS rn FROM ratings) SELECT customer_id,product_id,stars FROM r WHERE rn=1','Duplicate detection|ROW_NUMBER')
M('Verified Purchase Reviews','Return rating id for ratings where the same customer had a completed order containing that product on or before the review date.',"SELECT r.id FROM ratings r WHERE EXISTS(SELECT 1 FROM orders o JOIN items i ON i.order_id=o.id WHERE o.customer_id=r.customer_id AND i.product_id=r.product_id AND o.status='completed' AND o.order_date<=r.review_date)",'Semi-joins|EXISTS')
M('One-Star Share','Return product_id and one_star_pct, the percentage of ratings equal to 1, rounded to 2 decimals.','SELECT product_id,ROUND(100.0*SUM(CASE WHEN stars=1 THEN 1 ELSE 0 END)/COUNT(*),2) AS one_star_pct FROM ratings GROUP BY product_id','Conditional aggregation')
M('Rating Change from Previous','Return rating id and star_change versus the previous rating for that customer-product pair, ordered by review_date then id. First rating gets NULL.','SELECT id,stars-LAG(stars) OVER(PARTITION BY customer_id,product_id ORDER BY review_date,id) AS star_change FROM ratings','LAG and LEAD')
M('Daily Active Customers','Return activity_date and active_customers, counting each customer once per calendar day.','SELECT DAYKEY(event_time) AS activity_date,COUNT(DISTINCT customer_id) AS active_customers FROM events GROUP BY DAYKEY(event_time)','Date functions|Aggregate functions')
M('Cross Device Audience','Return customer_id for customers who used both mobile and web devices in events.',"SELECT customer_id FROM events GROUP BY customer_id HAVING COUNT(DISTINCT CASE WHEN device IN ('mobile','web') THEN device END)=2",'HAVING|Conditional aggregation')
M('View to Cart Audience','Return one row with viewers, cart_users and cart_rate_pct. Cart_users must have both a view and a cart event at any time, regardless of order. Percentage uses viewers; NULL for no viewers.',"WITH u AS(SELECT customer_id,MAX(CASE WHEN event_type='view' THEN 1 ELSE 0 END) AS v,MAX(CASE WHEN event_type='cart' THEN 1 ELSE 0 END) AS c FROM events GROUP BY customer_id) SELECT COALESCE(SUM(v),0) AS viewers,COALESCE(SUM(CASE WHEN v=1 AND c=1 THEN 1 ELSE 0 END),0) AS cart_users,ROUND(100.0*SUM(CASE WHEN v=1 AND c=1 THEN 1 ELSE 0 END)/NULLIF(SUM(v),0),2) AS cart_rate_pct FROM u",'Funnel analysis|CTEs')
M('Purchase without Prior View','Return purchase event id where that customer has no strictly earlier view timestamp. A view at exactly the purchase time does not count.',"SELECT p.id FROM events p WHERE p.event_type='purchase' AND NOT EXISTS(SELECT 1 FROM events v WHERE v.customer_id=p.customer_id AND v.event_type='view' AND v.event_time<p.event_time)",'NOT EXISTS|Funnel analysis')
M('Daily Event Type Pivot','Return activity_date, views, carts and purchases. Count event rows for each type per day.',"SELECT DAYKEY(event_time) AS activity_date,SUM(CASE WHEN event_type='view' THEN 1 ELSE 0 END) AS views,SUM(CASE WHEN event_type='cart' THEN 1 ELSE 0 END) AS carts,SUM(CASE WHEN event_type='purchase' THEN 1 ELSE 0 END) AS purchases FROM events GROUP BY DAYKEY(event_time)",'Pivoting|Conditional aggregation')
M('First Device Attribution','Return customer_id and first_device from the earliest event per customer, breaking ties by event id. Use a window first-value function.','SELECT DISTINCT customer_id,FIRST_VALUE(device) OVER(PARTITION BY customer_id ORDER BY event_time,id ROWS BETWEEN UNBOUNDED PRECEDING AND UNBOUNDED FOLLOWING) AS first_device FROM events','FIRST_VALUE and LAST_VALUE')
M('Last Device Across Full History','Return customer_id and last_device from the latest event, breaking ties by largest event id. Use LAST_VALUE with a full-partition frame.','SELECT DISTINCT customer_id,LAST_VALUE(device) OVER(PARTITION BY customer_id ORDER BY event_time,id ROWS BETWEEN UNBOUNDED PRECEDING AND UNBOUNDED FOLLOWING) AS last_device FROM events','FIRST_VALUE and LAST_VALUE|Window frames')
M('Event Duplicates to Remove','Treat events sharing customer_id,event_time,event_type,device as duplicates. Return id values that should be removed, retaining the smallest id per group. Do not issue DELETE.','WITH r AS(SELECT id,ROW_NUMBER() OVER(PARTITION BY customer_id,event_time,event_type,device ORDER BY id) AS rn FROM events) SELECT id FROM r WHERE rn>1','Duplicate detection|ROW_NUMBER')
M('Next-Day Event Retention','For each first activity date return cohort_date, cohort_size and retained_users, counting customers active the next calendar day.','WITH a AS(SELECT DISTINCT customer_id,DAYKEY(event_time) AS day FROM events),f AS(SELECT customer_id,MIN(day) AS first_day FROM a GROUP BY customer_id) SELECT f.first_day AS cohort_date,COUNT(*) AS cohort_size,SUM(CASE WHEN EXISTS(SELECT 1 FROM a WHERE a.customer_id=f.customer_id AND DIFFDAY(a.day,f.first_day)=1) THEN 1 ELSE 0 END) AS retained_users FROM f GROUP BY f.first_day','Retention|Cohort analysis')
M('Seven-Day Signup Activation','Return country, signups and activated. Activated means at least one event from signup day through day 6 inclusive; compare calendar dates.','SELECT c.country,COUNT(*) AS signups,SUM(CASE WHEN EXISTS(SELECT 1 FROM events e WHERE e.customer_id=c.id AND DIFFDAY(DAYKEY(e.event_time),c.signup_date) BETWEEN 0 AND 6) THEN 1 ELSE 0 END) AS activated FROM customers c GROUP BY c.country','Conversion rates|EXISTS')
M('January Cohort February Buyers','Return customer id for January 2025 signups who placed a completed order in February 2025.',"SELECT c.id FROM customers c WHERE c.signup_date>='2025-01-01' AND c.signup_date<'2025-02-01' AND EXISTS(SELECT 1 FROM orders o WHERE o.customer_id=c.id AND o.status='completed' AND o.order_date>='2025-02-01' AND o.order_date<'2025-03-01')",'Cohort analysis|Semi-joins')
M('Monthly Revenue by Signup Cohort','Return cohort_month, order_month and revenue across completed orders by customer signup month.',"SELECT MONTHKEY(c.signup_date) AS cohort_month,MONTHKEY(o.order_date) AS order_month,SUM(o.amount) AS revenue FROM customers c JOIN orders o ON o.customer_id=c.id WHERE o.status='completed' GROUP BY MONTHKEY(c.signup_date),MONTHKEY(o.order_date)",'Cohort analysis|Revenue analytics')
M('Subscription Snapshot','At the start of 2025-02-01, return plan, active_records and monthly_revenue. A subscription is active when start_date<=snapshot and end_date is NULL or strictly after snapshot.',"SELECT plan,COUNT(*) AS active_records,SUM(monthly_fee) AS monthly_revenue FROM subscriptions WHERE start_date<='2025-02-01' AND (end_date IS NULL OR end_date>'2025-02-01') GROUP BY plan",'Date functions|Business analytics')
M('Subscription Upgrades','Return customer_id, subscription_id and fee_increase when a subscription’s fee is greater than the previous subscription fee for that customer. Order records by start_date then id.','WITH r AS(SELECT *,LAG(monthly_fee) OVER(PARTITION BY customer_id ORDER BY start_date,id) AS previous_fee FROM subscriptions) SELECT customer_id,id AS subscription_id,monthly_fee-previous_fee AS fee_increase FROM r WHERE monthly_fee>previous_fee','LAG and LEAD')
M('Lapsed Then Returned','Return customer_id and returning_subscription_id when a subscription starts strictly after the previous subscription’s non-NULL end_date. Order by start_date then id.','WITH r AS(SELECT *,LAG(end_date) OVER(PARTITION BY customer_id ORDER BY start_date,id) AS previous_end FROM subscriptions) SELECT customer_id,id AS returning_subscription_id FROM r WHERE start_date>previous_end','Churn analysis|LAG and LEAD')
M('Paid Plan Mix','Return plan, record_count and fee_share_pct over subscription records with monthly_fee>0. Divide each plan’s summed fees by total fees and round to 2 decimals.','WITH p AS(SELECT plan,COUNT(*) AS record_count,SUM(monthly_fee) AS fee FROM subscriptions WHERE monthly_fee>0 GROUP BY plan) SELECT plan,record_count,ROUND(100.0*fee/SUM(fee) OVER(),2) AS fee_share_pct FROM p','Window functions|Business analytics')
M('Ended Subscription Duration','Return plan and average_days for ended subscriptions, averaging end_date-start_date in calendar days, rounded to 2 decimals.','SELECT plan,ROUND(AVG(DIFFDAY(end_date,start_date)),2) AS average_days FROM subscriptions WHERE end_date IS NOT NULL GROUP BY plan','Date functions|Aggregate functions')
M('Subscription Customers without Purchases','Return distinct customer_id from subscriptions when that customer has no completed orders.',"SELECT DISTINCT s.customer_id FROM subscriptions s WHERE NOT EXISTS(SELECT 1 FROM orders o WHERE o.customer_id=s.customer_id AND o.status='completed')",'Anti-joins')
M('Support Resolution Minutes','Return priority and average_minutes for resolved tickets, using elapsed whole minutes per ticket and rounding the average to 2 decimals.','SELECT priority,ROUND(AVG(DIFFMIN(resolved_at,opened_at)),2) AS average_minutes FROM tickets WHERE resolved_at IS NOT NULL GROUP BY priority','Date functions|Business analytics')
M('High Priority SLA','Return resolved_count, breached_count and breach_pct for resolved high priority tickets. A breach is resolution taking more than 120 whole minutes; percentage NULL if no resolved tickets.',"SELECT COUNT(*) AS resolved_count,COALESCE(SUM(CASE WHEN DIFFMIN(resolved_at,opened_at)>120 THEN 1 ELSE 0 END),0) AS breached_count,ROUND(100.0*SUM(CASE WHEN DIFFMIN(resolved_at,opened_at)>120 THEN 1 ELSE 0 END)/NULLIF(COUNT(*),0),2) AS breach_pct FROM tickets WHERE priority='high' AND resolved_at IS NOT NULL",'Conditional aggregation|Business analytics')
M('Most Recent Ticket per Customer','Return customer_id, ticket_id and priority for the latest ticket per customer, breaking opened_at ties by id descending.','WITH r AS(SELECT *,ROW_NUMBER() OVER(PARTITION BY customer_id ORDER BY opened_at DESC,id DESC) AS rn FROM tickets) SELECT customer_id,id AS ticket_id,priority FROM r WHERE rn=1','ROW_NUMBER')
M('Repeat Support Contacts','Return customer_id and contact_count for customers with two or more tickets. Also return unresolved_count.','SELECT customer_id,COUNT(*) AS contact_count,SUM(CASE WHEN resolved_at IS NULL THEN 1 ELSE 0 END) AS unresolved_count FROM tickets GROUP BY customer_id HAVING COUNT(*)>=2','HAVING|Conditional aggregation')
M('Customer Support Exposure','Return every customer id, order_count and ticket_count, counting each original order and ticket exactly once.','WITH o AS(SELECT customer_id,COUNT(*) AS n FROM orders GROUP BY customer_id),t AS(SELECT customer_id,COUNT(*) AS n FROM tickets GROUP BY customer_id) SELECT c.id,COALESCE(o.n,0) AS order_count,COALESCE(t.n,0) AS ticket_count FROM customers c LEFT JOIN o ON o.customer_id=c.id LEFT JOIN t ON t.customer_id=c.id','Complex joins|CTEs')
M('Courier On-Time Rate','Return every courier id and on_time_pct among delivered parcels. Delivery at promised_at is on time. Return NULL for couriers with no delivered parcels; round to 2 decimals.','SELECT c.id,ROUND(100.0*SUM(CASE WHEN d.delivered_at<=d.promised_at THEN 1 ELSE 0 END)/NULLIF(COUNT(d.delivered_at),0),2) AS on_time_pct FROM couriers c LEFT JOIN deliveries d ON d.courier_id=c.id GROUP BY c.id','LEFT joins|Conditional aggregation')
M('City Delivery Backlog','Return city and pending_count of assigned parcels not delivered, including cities with zero.','SELECT c.city,SUM(CASE WHEN d.order_id IS NOT NULL AND d.delivered_at IS NULL THEN 1 ELSE 0 END) AS pending_count FROM couriers c LEFT JOIN deliveries d ON d.courier_id=c.id GROUP BY c.city','LEFT joins|NULL handling')
M('Longest Courier Route','Return courier_id, order_id and distance_km for each courier’s longest route, retaining all ties.','WITH r AS(SELECT *,RANK() OVER(PARTITION BY courier_id ORDER BY distance_km DESC) AS rk FROM deliveries) SELECT courier_id,order_id,distance_km FROM r WHERE rk=1','RANK|Top N per group')
M('Average Positive Delivery Delay','Return courier_id and average_late_minutes using only parcels delivered late. Count elapsed whole minutes and round the average to 2 decimals.','SELECT courier_id,ROUND(AVG(DIFFMIN(delivered_at,promised_at)),2) AS average_late_minutes FROM deliveries WHERE delivered_at>promised_at GROUP BY courier_id','Date functions|Aggregate functions')
M('Delivery Revenue Exposure','Return courier_id and undelivered_value, summing order.amount for undelivered parcels on completed orders.',"SELECT d.courier_id,SUM(o.amount) AS undelivered_value FROM deliveries d JOIN orders o ON o.id=d.order_id WHERE d.delivered_at IS NULL AND o.status='completed' GROUP BY d.courier_id",'INNER joins|Revenue analytics')
M('January Advertising Cost per Click','Return channel and cost_per_click from January 2025 ad_spend, using total spend/total clicks; NULL for zero clicks and round to 2 decimals.',"SELECT channel,ROUND(1.0*SUM(spend)/NULLIF(SUM(clicks),0),2) AS cost_per_click FROM ad_spend WHERE day>='2025-01-01' AND day<'2025-02-01' GROUP BY channel",'Business analytics|NULL handling')
M('Channel Acquisition Cost','Return each advertising channel and acquisition_cost = total advertising spend/all customer signups attributed to it. Return NULL when a channel has no signups; round to 2 decimals.','WITH s AS(SELECT channel,SUM(spend) AS spend FROM ad_spend GROUP BY channel),c AS(SELECT channel,COUNT(*) AS n FROM customers GROUP BY channel) SELECT s.channel,ROUND(1.0*s.spend/NULLIF(c.n,0),2) AS acquisition_cost FROM s LEFT JOIN c ON c.channel=s.channel','CTEs|Business analytics')
M('Marketing Return on Spend','For each advertising channel return channel and revenue_per_spend: all-time completed revenue from attributed customers divided by all-time spend, rounded to 2 decimals. Missing revenue is zero, zero spend yields NULL.',"WITH s AS(SELECT channel,SUM(spend) AS spend FROM ad_spend GROUP BY channel),r AS(SELECT c.channel,SUM(o.amount) AS revenue FROM customers c JOIN orders o ON o.customer_id=c.id WHERE o.status='completed' GROUP BY c.channel) SELECT s.channel,ROUND(1.0*COALESCE(r.revenue,0)/NULLIF(s.spend,0),2) AS revenue_per_spend FROM s LEFT JOIN r ON r.channel=s.channel",'Complex joins|Revenue analytics')
M('Daily Spend Running Total','Return day, channel and cumulative_spend within each channel, ordered by day. There is at most one ad_spend record per channel per day.','SELECT day,channel,SUM(spend) OVER(PARTITION BY channel ORDER BY day ROWS UNBOUNDED PRECEDING) AS cumulative_spend FROM ad_spend','Running totals')
M('Click Efficiency Ranking','Return channel and click_rank based on all-time total clicks/total impressions, highest first. Exclude channels with zero total impressions and use DENSE_RANK for ties.','WITH c AS(SELECT channel,1.0*SUM(clicks)/SUM(impressions) AS rate FROM ad_spend GROUP BY channel HAVING SUM(impressions)>0) SELECT channel,DENSE_RANK() OVER(ORDER BY rate DESC) AS click_rank FROM c','DENSE_RANK|Business analytics')
M('Account Closing Balances','Return every account id and balance: credits minus debits across its ledger. No transactions means balance zero.',"SELECT a.id,COALESCE(SUM(CASE WHEN l.kind='credit' THEN l.amount ELSE -l.amount END),0) AS balance FROM accounts a LEFT JOIN ledger l ON l.account_id=a.id GROUP BY a.id",'LEFT joins|CASE WHEN',company='Deutsche Bank')
M('Negative Balance Accounts','Return account_id and balance for accounts whose total credits minus debits is below zero.',"SELECT account_id,SUM(CASE WHEN kind='credit' THEN amount ELSE -amount END) AS balance FROM ledger GROUP BY account_id HAVING SUM(CASE WHEN kind='credit' THEN amount ELSE -amount END)<0",'HAVING|Business analytics')
M('Transaction Running Balance','Return ledger id, account_id and running_balance after each transaction, ordering by txn_date then id within each account. Initial balance is zero.',"SELECT id,account_id,SUM(CASE WHEN kind='credit' THEN amount ELSE -amount END) OVER(PARTITION BY account_id ORDER BY txn_date,id ROWS UNBOUNDED PRECEDING) AS running_balance FROM ledger",'Running totals|Window frames')
M('Suspicious Duplicate Debits','Return account_id, txn_date, merchant, amount and duplicate_count for debit groups with identical values in these four fields and more than one row.',"SELECT account_id,txn_date,merchant,amount,COUNT(*) AS duplicate_count FROM ledger WHERE kind='debit' GROUP BY account_id,txn_date,merchant,amount HAVING COUNT(*)>1",'Duplicate detection',company='PayPal')
M('Customer Combined Balance','Return every customer id and combined_balance across all their accounts. Credits add and debits subtract; absent accounts or transactions contribute zero.',"SELECT c.id,COALESCE(SUM(CASE WHEN l.kind='credit' THEN l.amount ELSE -l.amount END),0) AS combined_balance FROM customers c LEFT JOIN accounts a ON a.customer_id=c.id LEFT JOIN ledger l ON l.account_id=a.id GROUP BY c.id",'Complex joins')
M('Largest Debit Merchant per Account','Return account_id, merchant and spent for the merchant with greatest total debit amount per account. Exclude NULL merchants and include ties.',"WITH m AS(SELECT account_id,merchant,SUM(amount) AS spent FROM ledger WHERE kind='debit' AND merchant IS NOT NULL GROUP BY account_id,merchant),r AS(SELECT *,RANK() OVER(PARTITION BY account_id ORDER BY spent DESC) AS rk FROM m) SELECT account_id,merchant,spent FROM r WHERE rk=1",'RANK|CTEs')
M('Credit to Debit Ratio','Return account_id and credit_debit_ratio across ledger records, rounded to 2 decimals. If total debits are zero, return NULL.',"SELECT account_id,ROUND(1.0*SUM(CASE WHEN kind='credit' THEN amount ELSE 0 END)/NULLIF(SUM(CASE WHEN kind='debit' THEN amount ELSE 0 END),0),2) AS credit_debit_ratio FROM ledger GROUP BY account_id",'Conditional aggregation|NULL handling')
M('Managers with Large Teams','Return manager_id and report_count for managers with at least three direct reports. Exclude NULL manager_id.','SELECT manager_id,COUNT(*) AS report_count FROM employees WHERE manager_id IS NOT NULL GROUP BY manager_id HAVING COUNT(*)>=3','HAVING|Self joins')
M('Highest Department Salary Ties','Return department, id and salary for employees earning their department’s highest known salary. Include ties and omit departments with all NULL salaries.','SELECT e.department,e.id,e.salary FROM employees e WHERE e.salary=(SELECT MAX(x.salary) FROM employees x WHERE x.department=e.department)','Correlated subqueries')
M('Project Staffing Cost','Return every project id and estimated_cost = sum(employee salary/2080*assigned hours). Ignore unknown salaries; projects without known staffing cost return zero. Round to 2 decimals.','SELECT p.id,ROUND(COALESCE(SUM(e.salary/2080.0*a.hours),0),2) AS estimated_cost FROM projects p LEFT JOIN assignments a ON a.project_id=p.id LEFT JOIN employees e ON e.id=a.employee_id GROUP BY p.id','Complex joins|Business analytics')
M('Unassigned Employees','Return employee id and name when the employee has no project assignment.','SELECT e.id,e.name FROM employees e LEFT JOIN assignments a ON a.employee_id=e.id WHERE a.employee_id IS NULL','Anti-joins')
M('Multi-Project Workload','Return employee_id, project_count and total_hours for employees assigned to at least two distinct projects.','SELECT employee_id,COUNT(DISTINCT project_id) AS project_count,SUM(hours) AS total_hours FROM assignments GROUP BY employee_id HAVING COUNT(DISTINCT project_id)>=2','HAVING')
M('Department Project Reach','Return department and project_count, counting distinct projects staffed by employees in that department; include departments with zero.','SELECT e.department,COUNT(DISTINCT a.project_id) AS project_count FROM employees e LEFT JOIN assignments a ON a.employee_id=e.id GROUP BY e.department','LEFT joins|Aggregate functions')
M('Project Hours Share','Return employee_id, project_id and hours_pct of that project’s total assignment hours, rounded to 2 decimals; zero project hours gives NULL.','SELECT employee_id,project_id,ROUND(100.0*hours/NULLIF(SUM(hours) OVER(PARTITION BY project_id),0),2) AS hours_pct FROM assignments','Window functions')
M('Department Hiring Sequence','Return department, id and hire_number ordered within department by hired_date then id.','SELECT department,id,ROW_NUMBER() OVER(PARTITION BY department ORDER BY hired_date,id) AS hire_number FROM employees','ROW_NUMBER')
M('Coworker Project Pairs','Return employee_1, employee_2 and shared_projects for employee pairs sharing at least one project. Always employee_1<employee_2 and count distinct shared projects.','SELECT a.employee_id AS employee_1,b.employee_id AS employee_2,COUNT(DISTINCT a.project_id) AS shared_projects FROM assignments a JOIN assignments b ON b.project_id=a.project_id AND a.employee_id<b.employee_id GROUP BY a.employee_id,b.employee_id','Self joins')
M('Department Salary Spread','Return department, minimum_salary, maximum_salary and spread (max minus min) using known salaries. Include all departments; all-NULL departments produce NULL metrics.','SELECT department,MIN(salary) AS minimum_salary,MAX(salary) AS maximum_salary,MAX(salary)-MIN(salary) AS spread FROM employees GROUP BY department','Aggregate functions|NULL handling')
M('Stock Replenishments','Return product_id, day and units_added when units increased from the previous observed snapshot. Order snapshots by day; omit first observations.','WITH r AS(SELECT *,LAG(units) OVER(PARTITION BY product_id ORDER BY day) AS previous_units FROM stock) SELECT product_id,day,units-previous_units AS units_added FROM r WHERE units>previous_units','LAG and LEAD')
M('Latest Inventory Snapshot','Return every product id, snapshot_day and units from its most recent stock snapshot. Products with no snapshots have NULL day and units.','WITH r AS(SELECT *,ROW_NUMBER() OVER(PARTITION BY product_id ORDER BY day DESC) AS rn FROM stock) SELECT p.id,r.day AS snapshot_day,r.units FROM products p LEFT JOIN r ON r.product_id=p.id AND r.rn=1','LEFT joins|ROW_NUMBER')
M('Inventory Value by Category','Value each product using its latest observed stock units times catalogue price. Return category and inventory_value, with missing snapshots valued at zero.','WITH r AS(SELECT *,ROW_NUMBER() OVER(PARTITION BY product_id ORDER BY day DESC) AS rn FROM stock) SELECT p.category,SUM(COALESCE(r.units,0)*p.price) AS inventory_value FROM products p LEFT JOIN r ON r.product_id=p.id AND r.rn=1 GROUP BY p.category','CTEs|Business analytics')
M('Titles with Repeat Viewers','Return title and repeat_viewers, counting customers with at least two watch records for that title. Only include titles with repeat viewers.','WITH r AS(SELECT title,customer_id FROM watches GROUP BY title,customer_id HAVING COUNT(*)>=2) SELECT title,COUNT(*) AS repeat_viewers FROM r GROUP BY title','CTEs|HAVING')
M('Viewer Favorite Genre','Return customer_id, genre and watched_minutes for every genre tied for that viewer’s largest total watch time.','WITH g AS(SELECT customer_id,genre,SUM(minutes) AS watched_minutes FROM watches GROUP BY customer_id,genre),r AS(SELECT *,DENSE_RANK() OVER(PARTITION BY customer_id ORDER BY watched_minutes DESC) AS rk FROM g) SELECT customer_id,genre,watched_minutes FROM r WHERE rk=1','DENSE_RANK|Customer segmentation')
M('Watch Time by Country','Return country and watched_minutes from all watch records joined to customers.','SELECT c.country,SUM(w.minutes) AS watched_minutes FROM customers c JOIN watches w ON w.customer_id=c.id GROUP BY c.country','INNER joins|Business analytics')
M('Viewers Exploring Genres','Return customer_id and genre_count for viewers with at least two distinct genres.','SELECT customer_id,COUNT(DISTINCT genre) AS genre_count FROM watches GROUP BY customer_id HAVING COUNT(DISTINCT genre)>=2','HAVING')
M('Daily Watch Rank','Return watched_at, customer_id, minutes and daily_rank based on each customer’s total minutes on that date, descending; RANK ties share rank and leave gaps.','WITH d AS(SELECT watched_at,customer_id,SUM(minutes) AS minutes FROM watches GROUP BY watched_at,customer_id) SELECT watched_at,customer_id,minutes,RANK() OVER(PARTITION BY watched_at ORDER BY minutes DESC) AS daily_rank FROM d','RANK|CTEs')
M('Social Connection Counts','Each friendships row is an undirected edge stored once. Return every customer id and friend_count, including zero.','WITH edges AS(SELECT customer_id AS person,friend_id AS friend FROM friendships UNION ALL SELECT friend_id,customer_id FROM friendships) SELECT c.id,COUNT(e.friend) AS friend_count FROM customers c LEFT JOIN edges e ON e.person=c.id GROUP BY c.id','UNION ALL|LEFT joins',company='LinkedIn')
M('Same-Country Friendships','Return customer_id and friend_id for friendship edges whose two customers share a country. Preserve stored edge orientation.','SELECT f.customer_id,f.friend_id FROM friendships f JOIN customers a ON a.id=f.customer_id JOIN customers b ON b.id=f.friend_id WHERE a.country=b.country','Complex joins',company='Meta')
M('Referral Signups per Month','Return signup_month and referred_signups counting customers with a non-NULL referrer_id.','SELECT MONTHKEY(signup_date) AS signup_month,COUNT(*) AS referred_signups FROM customers WHERE referrer_id IS NOT NULL GROUP BY MONTHKEY(signup_date)','Date functions|GROUP BY')
M('Missing Orders or Missing Lines','Return issue and order_id: missing_lines for orders without items, and orphan_lines for item order_ids absent from orders. Deduplicate orphan order_ids.',"SELECT 'missing_lines' AS issue,o.id AS order_id FROM orders o LEFT JOIN items i ON i.order_id=o.id WHERE i.order_id IS NULL UNION ALL SELECT DISTINCT 'orphan_lines',i.order_id FROM items i LEFT JOIN orders o ON o.id=i.order_id WHERE o.id IS NULL",'UNION ALL|FULL join emulation|Data cleaning')
M('Right Join Catalogue Audit','Use a RIGHT JOIN to return every product id and line_count, including products never referenced in items.','SELECT p.id,COUNT(i.order_id) AS line_count FROM items i RIGHT JOIN products p ON p.id=i.product_id GROUP BY p.id','RIGHT joins')
M('January Sargable Orders','Return id and amount for completed orders during January 2025. Use a half-open date range, allowing an index on order_date to be useful.',"SELECT id,amount FROM orders WHERE status='completed' AND order_date>='2025-01-01' AND order_date<'2025-02-01'",'Query optimization|Date functions','Avoid wrapping the indexed date column in a function. A half-open range handles every January date.')
M('Customers Buying Both Target Products','Return customer_id for customers with completed purchases of both product 1 and product 2, possibly in different orders.',"SELECT o.customer_id FROM orders o JOIN items i ON i.order_id=o.id WHERE o.status='completed' AND i.product_id IN (1,2) GROUP BY o.customer_id HAVING COUNT(DISTINCT i.product_id)=2",'Relational division|HAVING')
M('Customer Order Frequency Rank','Return customer_id, order_count and frequency_rank using DENSE_RANK by completed order count descending.',"WITH c AS(SELECT customer_id,COUNT(*) AS order_count FROM orders WHERE status='completed' GROUP BY customer_id) SELECT customer_id,order_count,DENSE_RANK() OVER(ORDER BY order_count DESC) AS frequency_rank FROM c",'DENSE_RANK|Customer segmentation')
M('Customer Revenue and Watch Engagement','Return every customer id, completed_revenue and watch_minutes. Aggregate orders and watches separately before joining, using zero for absent activity.',"WITH o AS(SELECT customer_id,SUM(amount) AS revenue FROM orders WHERE status='completed' GROUP BY customer_id),w AS(SELECT customer_id,SUM(minutes) AS minutes FROM watches GROUP BY customer_id) SELECT c.id,COALESCE(o.revenue,0) AS completed_revenue,COALESCE(w.minutes,0) AS watch_minutes FROM customers c LEFT JOIN o ON o.customer_id=c.id LEFT JOIN w ON w.customer_id=c.id",'Complex joins|CTEs')
M('Order Value with Previous and Next','For completed orders return id, previous_amount and next_amount in that customer’s sequence ordered by order_date then id. Boundary values are NULL.',"SELECT id,LAG(amount) OVER(PARTITION BY customer_id ORDER BY order_date,id) AS previous_amount,LEAD(amount) OVER(PARTITION BY customer_id ORDER BY order_date,id) AS next_amount FROM orders WHERE status='completed'",'LAG and LEAD')
# 50 advanced problems: calendar boundaries, windows, recursion, division and intervals.
H('Longest Calendar Activity Streak','Return customer_id and longest_streak of consecutive calendar days with events. Multiple events on a day count once; missing days break streaks.','WITH d AS(SELECT DISTINCT customer_id,DAYKEY(event_time) AS day FROM events),p AS(SELECT *,LAG(day) OVER(PARTITION BY customer_id ORDER BY day) AS prev FROM d),g AS(SELECT *,SUM(CASE WHEN DIFFDAY(day,prev)=1 THEN 0 ELSE 1 END) OVER(PARTITION BY customer_id ORDER BY day ROWS UNBOUNDED PRECEDING) AS grp FROM p),s AS(SELECT customer_id,grp,COUNT(*) AS n FROM g GROUP BY customer_id,grp) SELECT customer_id,MAX(n) AS longest_streak FROM s GROUP BY customer_id','Gaps and Islands|Consecutive dates')
H('Thirty-Minute Sessionization','Return event id, customer_id and session_number. Events are ordered by event_time then id. Start a session for the first event or when the whole-minute gap from the previous event is greater than 30.','WITH p AS(SELECT *,LAG(event_time) OVER(PARTITION BY customer_id ORDER BY event_time,id) AS prev FROM events),s AS(SELECT *,CASE WHEN prev IS NULL OR DIFFMIN(event_time,prev)>30 THEN 1 ELSE 0 END AS new_session FROM p) SELECT id,customer_id,SUM(new_session) OVER(PARTITION BY customer_id ORDER BY event_time,id ROWS UNBOUNDED PRECEDING) AS session_number FROM s','Sessionization|Window frames')
H('Session Conversion Rate','Use the same customer session rule: first event or whole-minute gap>30 starts a session, ties ordered by id. Return sessions, converted_sessions and conversion_pct where a converted session contains a purchase; zero sessions gives NULL percentage.',"WITH p AS(SELECT *,LAG(event_time) OVER(PARTITION BY customer_id ORDER BY event_time,id) AS prev FROM events),g AS(SELECT *,SUM(CASE WHEN prev IS NULL OR DIFFMIN(event_time,prev)>30 THEN 1 ELSE 0 END) OVER(PARTITION BY customer_id ORDER BY event_time,id ROWS UNBOUNDED PRECEDING) AS grp FROM p),s AS(SELECT customer_id,grp,MAX(CASE WHEN event_type='purchase' THEN 1 ELSE 0 END) AS converted FROM g GROUP BY customer_id,grp) SELECT COUNT(*) AS sessions,COALESCE(SUM(converted),0) AS converted_sessions,ROUND(100.0*SUM(converted)/NULLIF(COUNT(*),0),2) AS conversion_pct FROM s",'Sessionization|Conversion rates')
H('Strict One-Hour Funnel','Return distinct customer_id where a view is followed by a strictly later cart and then a strictly later purchase, with whole-minute view-to-purchase elapsed time <=60.',"SELECT DISTINCT v.customer_id FROM events v JOIN events c ON c.customer_id=v.customer_id AND c.event_type='cart' AND c.event_time>v.event_time JOIN events p ON p.customer_id=v.customer_id AND p.event_type='purchase' AND p.event_time>c.event_time WHERE v.event_type='view' AND DIFFMIN(p.event_time,v.event_time)<=60",'Funnel analysis|Complex joins')
H('Time from First View to Conversion','Return customer_id and minutes_to_purchase from their earliest view timestamp to their earliest strictly later purchase timestamp. Exclude customers without both; use whole elapsed minutes.',"WITH v AS(SELECT customer_id,MIN(event_time) AS first_view FROM events WHERE event_type='view' GROUP BY customer_id),p AS(SELECT v.customer_id,v.first_view,MIN(e.event_time) AS purchase FROM v JOIN events e ON e.customer_id=v.customer_id AND e.event_type='purchase' AND e.event_time>v.first_view GROUP BY v.customer_id,v.first_view) SELECT customer_id,DIFFMIN(purchase,first_view) AS minutes_to_purchase FROM p",'Funnel analysis|CTEs')
H('Seven Calendar Day Revenue','For each observed completed-order date return order_date and seven_day_revenue for that date and the previous 6 calendar days. Do not use a seven-row window.',"WITH d AS(SELECT order_date,SUM(amount) AS revenue FROM orders WHERE status='completed' GROUP BY order_date) SELECT a.order_date,SUM(b.revenue) AS seven_day_revenue FROM d a JOIN d b ON DIFFDAY(a.order_date,b.order_date) BETWEEN 0 AND 6 GROUP BY a.order_date",'Rolling averages|Date functions')
H('Three Consecutive Purchase Months','Return customer_id with completed orders in at least three consecutive calendar months. Multiple orders in a month count once.',"WITH m AS(SELECT DISTINCT customer_id,MONTHKEY(order_date) AS month FROM orders WHERE status='completed'),p AS(SELECT *,LAG(month,2) OVER(PARTITION BY customer_id ORDER BY month) AS two_back FROM m) SELECT DISTINCT customer_id FROM p WHERE MONTHGAP(month,two_back)=2",'Consecutive dates|LAG and LEAD')
H('Monthly Purchase Cohort Retention','Cohort customers by their first completed-order month. Return cohort_month, month_index and retained_customers for observed completed-order activity months, including index 0. Month index is calendar-month difference.',"WITH m AS(SELECT DISTINCT customer_id,MONTHKEY(order_date) AS month FROM orders WHERE status='completed'),f AS(SELECT customer_id,MIN(month) AS cohort FROM m GROUP BY customer_id) SELECT f.cohort AS cohort_month,MONTHGAP(m.month,f.cohort) AS month_index,COUNT(*) AS retained_customers FROM m JOIN f ON f.customer_id=m.customer_id GROUP BY f.cohort,MONTHGAP(m.month,f.cohort)",'Cohort analysis|Retention')
H('Median Known Salary by Department','Return department and median_salary of non-NULL salaries. For even counts use the average of the two middle values. Do not deduplicate salary ties.','WITH r AS(SELECT department,salary,ROW_NUMBER() OVER(PARTITION BY department ORDER BY salary,id) AS rn,COUNT(*) OVER(PARTITION BY department) AS n FROM employees WHERE salary IS NOT NULL) SELECT department,ROUND(AVG(salary),2) AS median_salary FROM r WHERE rn IN(FLOOR((n+1)/2.0),FLOOR((n+2)/2.0)) GROUP BY department','Percentiles and medians|ROW_NUMBER')
H('Ninetieth Percentile Order Value','Return country and p90_order_value using the nearest-rank definition: the value at position CEILING(0.9*N) among that country’s completed orders sorted by amount then order id.',"WITH r AS(SELECT c.country,o.amount,ROW_NUMBER() OVER(PARTITION BY c.country ORDER BY o.amount,o.id) AS rn,COUNT(*) OVER(PARTITION BY c.country) AS n FROM customers c JOIN orders o ON o.customer_id=c.id WHERE o.status='completed') SELECT country,amount AS p90_order_value FROM r WHERE rn=CEIL(0.9*n)",'Percentiles and medians|Window functions')
H('Full Reporting Tree Size','Return every employee id and descendant_count, counting all direct and indirect reports and excluding the employee. The manager hierarchy is acyclic and has depth below 50.','WITH RECURSIVE tree AS(SELECT id AS ancestor,id AS descendant FROM employees UNION ALL SELECT t.ancestor,e.id FROM tree t JOIN employees e ON e.manager_id=t.descendant) SELECT ancestor AS id,COUNT(*)-1 AS descendant_count FROM tree GROUP BY ancestor','Recursive CTEs|Hierarchical queries')
H('Referral Roots and Depths','Return customer_id, root_id and depth in the customer referral forest. Roots have NULL referrer_id and depth 0. All non-NULL referrers exist and the forest is acyclic, depth below 50.','WITH RECURSIVE r AS(SELECT id AS customer_id,id AS root_id,0 AS depth FROM customers WHERE referrer_id IS NULL UNION ALL SELECT c.id,r.root_id,r.depth+1 FROM customers c JOIN r ON c.referrer_id=r.customer_id) SELECT customer_id,root_id,depth FROM r','Recursive CTEs|Hierarchical queries')
H('Employees Covering Every Project','Return employee id when the employee has an assignment on every project. Require at least one project to exist; zero-hour assignments count.','SELECT e.id FROM employees e WHERE EXISTS(SELECT 1 FROM projects) AND NOT EXISTS(SELECT 1 FROM projects p WHERE NOT EXISTS(SELECT 1 FROM assignments a WHERE a.employee_id=e.id AND a.project_id=p.id))','Relational division|NOT EXISTS')
H('Every Catalogue Category Purchased','Return customer id when completed order lines cover every category currently in products. Require a nonempty catalogue; zero-quantity lines still count as an order line.',"SELECT c.id FROM customers c WHERE EXISTS(SELECT 1 FROM products) AND NOT EXISTS(SELECT 1 FROM products p WHERE NOT EXISTS(SELECT 1 FROM orders o JOIN items i ON i.order_id=o.id JOIN products x ON x.id=i.product_id WHERE o.customer_id=c.id AND o.status='completed' AND x.category=p.category))",'Relational division|Complex joins')
H('Strict Product Set Supersets','Return customer_1 and customer_2 where customer_1’s set of products in completed orders is a strict superset of customer_2’s. Both must have a nonempty product set; ordered pairs are directional.',"WITH s AS(SELECT DISTINCT o.customer_id,i.product_id FROM orders o JOIN items i ON i.order_id=o.id WHERE o.status='completed'),u AS(SELECT DISTINCT customer_id FROM s) SELECT a.customer_id AS customer_1,b.customer_id AS customer_2 FROM u a CROSS JOIN u b WHERE a.customer_id<>b.customer_id AND NOT EXISTS(SELECT 1 FROM s y WHERE y.customer_id=b.customer_id AND NOT EXISTS(SELECT 1 FROM s x WHERE x.customer_id=a.customer_id AND x.product_id=y.product_id)) AND EXISTS(SELECT 1 FROM s x WHERE x.customer_id=a.customer_id AND NOT EXISTS(SELECT 1 FROM s y WHERE y.customer_id=b.customer_id AND y.product_id=x.product_id))",'Relational division|Correlated subqueries')
H('Friends of Friends Recommendations','Treat friendship rows as undirected unique edges. Return customer_1, customer_2 and mutual_friends for non-friend pairs sharing at least two friends. Require customer_1<customer_2.','WITH e AS(SELECT customer_id AS person,friend_id AS friend FROM friendships UNION ALL SELECT friend_id,customer_id FROM friendships) SELECT a.person AS customer_1,b.person AS customer_2,COUNT(DISTINCT a.friend) AS mutual_friends FROM e a JOIN e b ON a.friend=b.friend AND a.person<b.person WHERE NOT EXISTS(SELECT 1 FROM e direct WHERE direct.person=a.person AND direct.friend=b.person) GROUP BY a.person,b.person HAVING COUNT(DISTINCT a.friend)>=2','Self joins|Anti-joins')
H('Social Triangles','Treat friendships as undirected unique edges. Return a,b,c for fully connected triples with a<b<c, each triangle exactly once.','WITH e AS(SELECT customer_id AS person,friend_id AS friend FROM friendships UNION ALL SELECT friend_id,customer_id FROM friendships) SELECT x.person AS a,x.friend AS b,y.friend AS c FROM e x JOIN e y ON y.person=x.friend JOIN e z ON z.person=x.person AND z.friend=y.friend WHERE x.person<x.friend AND x.friend<y.friend','Complex joins|CTEs')
H('Product Pair Basket Support','Return product_1, product_2, shared_baskets and support_pct for pairs co-occurring in a completed order. product_1<product_2. Denominator is all completed orders, including orders without lines. Round percent to 2 decimals.',"WITH b AS(SELECT DISTINCT o.id AS order_id,i.product_id FROM orders o JOIN items i ON i.order_id=o.id WHERE o.status='completed') SELECT a.product_id AS product_1,b.product_id AS product_2,COUNT(*) AS shared_baskets,ROUND(100.0*COUNT(*)/(SELECT COUNT(*) FROM orders WHERE status='completed'),2) AS support_pct FROM b a JOIN b b ON b.order_id=a.order_id AND a.product_id<b.product_id GROUP BY a.product_id,b.product_id",'Complex joins|Business analytics')
H('Three-Month Revenue Acceleration','Return customer_id and ending_month when completed revenue increased strictly in three consecutive calendar months. Multiple qualifying windows for a customer are allowed.',"WITH m AS(SELECT customer_id,MONTHKEY(order_date) AS month,SUM(amount) AS revenue FROM orders WHERE status='completed' GROUP BY customer_id,MONTHKEY(order_date)),p AS(SELECT *,LAG(revenue) OVER(PARTITION BY customer_id ORDER BY month) AS r1,LAG(revenue,2) OVER(PARTITION BY customer_id ORDER BY month) AS r2,LAG(month,2) OVER(PARTITION BY customer_id ORDER BY month) AS m2 FROM m) SELECT customer_id,month AS ending_month FROM p WHERE MONTHGAP(month,m2)=2 AND revenue>r1 AND r1>r2",'LAG and LEAD|Revenue analytics')
H('Maximum Account Drawdown','Starting with balance zero, order each account’s ledger by txn_date then id. Return account_id and maximum_drawdown: the greatest fall from its historical peak balance, including the initial zero peak.',"WITH b AS(SELECT account_id,id,txn_date,SUM(CASE WHEN kind='credit' THEN amount ELSE -amount END) OVER(PARTITION BY account_id ORDER BY txn_date,id ROWS UNBOUNDED PRECEDING) AS balance FROM ledger),p AS(SELECT *,MAX(balance) OVER(PARTITION BY account_id ORDER BY txn_date,id ROWS UNBOUNDED PRECEDING) AS peak FROM b) SELECT account_id,MAX(CASE WHEN peak>0 THEN peak ELSE 0 END-balance) AS maximum_drawdown FROM p GROUP BY account_id",'Running totals|Window frames')
H('First Overdraft Entry','Return account_id and transaction_id for the first transaction leaving a negative running balance. Credits add, debits subtract; order by txn_date then id.',"WITH b AS(SELECT *,SUM(CASE WHEN kind='credit' THEN amount ELSE -amount END) OVER(PARTITION BY account_id ORDER BY txn_date,id ROWS UNBOUNDED PRECEDING) AS balance FROM ledger),r AS(SELECT *,ROW_NUMBER() OVER(PARTITION BY account_id ORDER BY txn_date,id) AS rn FROM b WHERE balance<0) SELECT account_id,id AS transaction_id FROM r WHERE rn=1",'Running totals|ROW_NUMBER')
H('Overdraft Recovery Transactions','Return transaction id and account_id when running balance transitions from negative to non-negative. Initial balance is zero, and ordering is txn_date then id.',"WITH b AS(SELECT *,SUM(CASE WHEN kind='credit' THEN amount ELSE -amount END) OVER(PARTITION BY account_id ORDER BY txn_date,id ROWS UNBOUNDED PRECEDING) AS balance FROM ledger),p AS(SELECT *,LAG(balance,1,0) OVER(PARTITION BY account_id ORDER BY txn_date,id) AS previous FROM b) SELECT id,account_id FROM p WHERE previous<0 AND balance>=0",'LAG and LEAD|Running totals')
H('Overlapping Subscription Records','Return customer_id, subscription_1 and subscription_2 for overlapping half-open subscription intervals [start_date,end_date). NULL end means unbounded. Exclude zero-length records and require subscription_1<subscription_2.','SELECT a.customer_id,a.id AS subscription_1,b.id AS subscription_2 FROM subscriptions a JOIN subscriptions b ON a.customer_id=b.customer_id AND a.id<b.id WHERE (a.end_date IS NULL OR a.end_date>a.start_date) AND (b.end_date IS NULL OR b.end_date>b.start_date) AND (b.end_date IS NULL OR a.start_date<b.end_date) AND (a.end_date IS NULL OR b.start_date<a.end_date)','Complex joins|Date functions')
H('Distinct Paid Coverage Days','For each customer with a positive-fee subscription, return customer_id and covered_days during Jan 1–7, 2025 inclusive. Count each calendar day once even with overlapping subscriptions; include zero coverage.',"WITH RECURSIVE days AS(SELECT CAST('2025-01-01' AS DATE) AS day UNION ALL SELECT SHIFT(day,1) FROM days WHERE day<'2025-01-07'),u AS(SELECT DISTINCT customer_id FROM subscriptions WHERE monthly_fee>0) SELECT u.customer_id,SUM(CASE WHEN EXISTS(SELECT 1 FROM subscriptions s WHERE s.customer_id=u.customer_id AND s.monthly_fee>0 AND s.start_date<=days.day AND (s.end_date IS NULL OR s.end_date>days.day)) THEN 1 ELSE 0 END) AS covered_days FROM u CROSS JOIN days GROUP BY u.customer_id",'Recursive CTEs|Date functions')
H('February Customer Churn','Among distinct customers active on 2025-02-01, count those not active on 2025-03-01. Return starting_customers, churned_customers and churn_pct rounded to 2 decimals; empty starting base yields NULL. Intervals are start-inclusive, end-exclusive.',"WITH a AS(SELECT DISTINCT customer_id FROM subscriptions WHERE start_date<='2025-02-01' AND (end_date IS NULL OR end_date>'2025-02-01')) SELECT COUNT(*) AS starting_customers,COALESCE(SUM(CASE WHEN NOT EXISTS(SELECT 1 FROM subscriptions s WHERE s.customer_id=a.customer_id AND s.start_date<='2025-03-01' AND (s.end_date IS NULL OR s.end_date>'2025-03-01')) THEN 1 ELSE 0 END),0) AS churned_customers,ROUND(100.0*SUM(CASE WHEN NOT EXISTS(SELECT 1 FROM subscriptions s WHERE s.customer_id=a.customer_id AND s.start_date<='2025-03-01' AND (s.end_date IS NULL OR s.end_date>'2025-03-01')) THEN 1 ELSE 0 END)/NULLIF(COUNT(*),0),2) AS churn_pct FROM a",'Churn analysis|Retention')
H('Net Revenue Retention Snapshot','For customers active on 2025-01-15, return starting_mrr, ending_mrr on 2025-02-15 and nrr_pct. Sum fees of all active records, including overlaps. Exclude later-acquired customers. Missing ending MRR is 0; zero starting total yields NULL percent.',"WITH a AS(SELECT customer_id,SUM(monthly_fee) AS mrr FROM subscriptions WHERE start_date<='2025-01-15' AND (end_date IS NULL OR end_date>'2025-01-15') GROUP BY customer_id),b AS(SELECT customer_id,SUM(monthly_fee) AS mrr FROM subscriptions WHERE start_date<='2025-02-15' AND (end_date IS NULL OR end_date>'2025-02-15') GROUP BY customer_id) SELECT COALESCE(SUM(a.mrr),0) AS starting_mrr,COALESCE(SUM(b.mrr),0) AS ending_mrr,ROUND(100.0*SUM(COALESCE(b.mrr,0))/NULLIF(SUM(a.mrr),0),2) AS nrr_pct FROM a LEFT JOIN b ON b.customer_id=a.customer_id",'Retention|Revenue analytics')
H('Plan Switches without Coverage Gap','Return customer_id, old_subscription_id and new_subscription_id when a record ends exactly when that customer’s next record starts and the plan changes. Next is defined by start_date then id.',"WITH s AS(SELECT *,LEAD(id) OVER(PARTITION BY customer_id ORDER BY start_date,id) AS next_id,LEAD(start_date) OVER(PARTITION BY customer_id ORDER BY start_date,id) AS next_start,LEAD(plan) OVER(PARTITION BY customer_id ORDER BY start_date,id) AS next_plan FROM subscriptions) SELECT customer_id,id AS old_subscription_id,next_id AS new_subscription_id FROM s WHERE end_date=next_start AND plan<>next_plan",'LAG and LEAD|Date functions')
H('Peak Concurrent Support Tickets','Return peak_open, the greatest number of simultaneously open tickets. Ticket intervals are [opened_at,resolved_at), NULL resolution stays open. Aggregate starts and resolutions at equal timestamps before a running sum; no tickets means 0.','WITH changes AS(SELECT opened_at AS t,1 AS delta FROM tickets UNION ALL SELECT resolved_at,-1 FROM tickets WHERE resolved_at IS NOT NULL),d AS(SELECT t,SUM(delta) AS delta FROM changes GROUP BY t),r AS(SELECT SUM(delta) OVER(ORDER BY t ROWS UNBOUNDED PRECEDING) AS open_count FROM d) SELECT COALESCE(MAX(open_count),0) AS peak_open FROM r','Running totals|UNION ALL')
H('Daily Support Backlog Calendar','For every date Jan 1–7 2025 return day and open_at_midnight, counting tickets opened by 00:00:00 and not resolved by then. Return zero for empty days.',"WITH RECURSIVE d AS(SELECT CAST('2025-01-01' AS DATE) AS day UNION ALL SELECT SHIFT(day,1) FROM d WHERE day<'2025-01-07') SELECT d.day,COUNT(t.id) AS open_at_midnight FROM d LEFT JOIN tickets t ON t.opened_at<=MIDNIGHT(d.day) AND (t.resolved_at IS NULL OR t.resolved_at>MIDNIGHT(d.day)) GROUP BY d.day",'Recursive CTEs|LEFT joins')
H('Courier Three-Delivery SLA','For every delivered parcel return order_id, courier_id and on_time_last_three_pct based on that courier’s current and previous two delivered parcels. Order by delivered_at then order_id; partial windows allowed, round to 2 decimals.','SELECT order_id,courier_id,ROUND(100.0*AVG(CASE WHEN delivered_at<=promised_at THEN 1.0 ELSE 0.0 END) OVER(PARTITION BY courier_id ORDER BY delivered_at,order_id ROWS BETWEEN 2 PRECEDING AND CURRENT ROW),2) AS on_time_last_three_pct FROM deliveries WHERE delivered_at IS NOT NULL','Window frames|Rolling averages')
H('Three Late Parcels in a Row','Return courier_id and ending_order_id for every run of three consecutive late delivered parcels. Order delivered parcels per courier by delivered_at then order_id; longer runs produce multiple endpoints.','WITH r AS(SELECT *,SUM(CASE WHEN delivered_at>promised_at THEN 1 ELSE 0 END) OVER(PARTITION BY courier_id ORDER BY delivered_at,order_id ROWS BETWEEN 2 PRECEDING AND CURRENT ROW) AS late_count FROM deliveries WHERE delivered_at IS NOT NULL) SELECT courier_id,order_id AS ending_order_id FROM r WHERE late_count=3','Consecutive events|Window frames')
H('Revenue Pareto Product Set','From completed line revenue, sort products by revenue descending then id. Return product_id and revenue for the smallest prefix whose cumulative revenue reaches at least 80% of total. Exclude zero or negative revenue products; no positive revenue yields no rows.',"WITH p AS(SELECT i.product_id,SUM(i.quantity*i.unit_price) AS revenue FROM items i JOIN orders o ON o.id=i.order_id WHERE o.status='completed' GROUP BY i.product_id HAVING SUM(i.quantity*i.unit_price)>0),r AS(SELECT *,SUM(revenue) OVER(ORDER BY revenue DESC,product_id ROWS UNBOUNDED PRECEDING) AS cumulative,SUM(revenue) OVER() AS total FROM p) SELECT product_id,revenue FROM r WHERE cumulative-revenue<0.8*total",'Running totals|Business analytics')
H('Thirty-Day Cohort Value','For each signup month return cohort_month, customers and revenue_per_signup. Revenue includes completed orders on days 0–29 after signup. Every signup stays in the denominator. Round to 2 decimals.',"WITH v AS(SELECT c.id,MONTHKEY(c.signup_date) AS cohort,COALESCE(SUM(o.amount),0) AS revenue FROM customers c LEFT JOIN orders o ON o.customer_id=c.id AND o.status='completed' AND DIFFDAY(o.order_date,c.signup_date) BETWEEN 0 AND 29 GROUP BY c.id,MONTHKEY(c.signup_date)) SELECT cohort AS cohort_month,COUNT(*) AS customers,ROUND(1.0*SUM(revenue)/COUNT(*),2) AS revenue_per_signup FROM v GROUP BY cohort",'Cohort analysis|Complex joins')
H('Monthly Buyer Lifecycle','For each customer’s observed completed purchase month return customer_id, month and lifecycle: new for first month, retained if previous active month was exactly one calendar month earlier, resurrected otherwise.',"WITH m AS(SELECT DISTINCT customer_id,MONTHKEY(order_date) AS month FROM orders WHERE status='completed'),p AS(SELECT *,LAG(month) OVER(PARTITION BY customer_id ORDER BY month) AS previous FROM m) SELECT customer_id,month,CASE WHEN previous IS NULL THEN 'new' WHEN MONTHGAP(month,previous)=1 THEN 'retained' ELSE 'resurrected' END AS lifecycle FROM p",'Retention|Customer segmentation')
H('Unconverted Cart Episodes','Return cart event id and customer_id when no purchase occurs at a strictly later timestamp within 60 whole minutes for the same customer. A purchase after 60 minutes does not rescue the cart.',"SELECT c.id,c.customer_id FROM events c WHERE c.event_type='cart' AND NOT EXISTS(SELECT 1 FROM events p WHERE p.customer_id=c.customer_id AND p.event_type='purchase' AND p.event_time>c.event_time AND DIFFMIN(p.event_time,c.event_time)<=60)",'Funnel analysis|Anti-joins')
H('Current Rating Category Score','Keep only the latest rating for each customer-product pair by review_date then id descending. Return category and average_stars across retained ratings, rounded to 2 decimals. Categories without retained ratings are omitted.','WITH r AS(SELECT *,ROW_NUMBER() OVER(PARTITION BY customer_id,product_id ORDER BY review_date DESC,id DESC) AS rn FROM ratings) SELECT p.category,ROUND(AVG(r.stars),2) AS average_stars FROM r JOIN products p ON p.id=r.product_id WHERE r.rn=1 GROUP BY p.category','Duplicate detection|Complex joins')
H('Customer-Weighted Basket Averages','For each country return customer_weighted_average and order_weighted_average over completed orders. The first averages per-customer mean order values equally; the second averages all orders. Exclude non-buyers and round both to 2 decimals.',"WITH c AS(SELECT x.country,o.customer_id,SUM(o.amount) AS revenue,COUNT(*) AS n FROM customers x JOIN orders o ON o.customer_id=x.id WHERE o.status='completed' GROUP BY x.country,o.customer_id) SELECT country,ROUND(AVG(1.0*revenue/n),2) AS customer_weighted_average,ROUND(1.0*SUM(revenue)/SUM(n),2) AS order_weighted_average FROM c GROUP BY country",'CTEs|Business analytics')
H('First Purchase Product Attribution','Attribute each customer’s first completed order amount equally across its distinct products, not line quantity. First order is by order_date then id. Return product_id and attributed_revenue rounded to 2 decimals; first orders with no lines contribute nothing.',"WITH r AS(SELECT *,ROW_NUMBER() OVER(PARTITION BY customer_id ORDER BY order_date,id) AS rn FROM orders WHERE status='completed'),b AS(SELECT DISTINCT r.id,r.amount,i.product_id FROM r JOIN items i ON i.order_id=r.id WHERE r.rn=1),w AS(SELECT *,COUNT(*) OVER(PARTITION BY id) AS n FROM b) SELECT product_id,ROUND(SUM(1.0*amount/n),2) AS attributed_revenue FROM w GROUP BY product_id",'ROW_NUMBER|Complex joins')
H('Peer Title Recommendations','For every pair (customer_id,title) where a direct friend watched that title but the customer never did, return recommending_friends as a distinct friend count. Treat friendships as undirected; repeated watches do not add votes.','WITH e AS(SELECT customer_id AS person,friend_id AS friend FROM friendships UNION ALL SELECT friend_id,customer_id FROM friendships) SELECT e.person AS customer_id,w.title,COUNT(DISTINCT e.friend) AS recommending_friends FROM e JOIN watches w ON w.customer_id=e.friend WHERE NOT EXISTS(SELECT 1 FROM watches own WHERE own.customer_id=e.person AND own.title=w.title) GROUP BY e.person,w.title','Complex joins|NOT EXISTS')
H('Engaged High-Value Customers','Return customer_id with at least three consecutive activity calendar days and at least 300 total completed order revenue. Deduplicate same-day activity.',"WITH d AS(SELECT DISTINCT customer_id,DAYKEY(event_time) AS day FROM events),p AS(SELECT *,LAG(day,2) OVER(PARTITION BY customer_id ORDER BY day) AS back2 FROM d),u AS(SELECT DISTINCT customer_id FROM p WHERE DIFFDAY(day,back2)=2),r AS(SELECT customer_id,SUM(amount) AS revenue FROM orders WHERE status='completed' GROUP BY customer_id) SELECT u.customer_id FROM u JOIN r ON r.customer_id=u.customer_id WHERE r.revenue>=300",'Consecutive dates|Customer segmentation')
H('Stockout Calendar Islands','Return product_id, start_day, end_day and days for every maximal consecutive-calendar-day run of zero stock. Positive-stock snapshots and missing dates both break runs.','WITH z AS(SELECT product_id,day,LAG(day) OVER(PARTITION BY product_id ORDER BY day) AS previous_zero FROM stock WHERE units=0),g AS(SELECT *,SUM(CASE WHEN DIFFDAY(day,previous_zero)=1 THEN 0 ELSE 1 END) OVER(PARTITION BY product_id ORDER BY day ROWS UNBOUNDED PRECEDING) AS grp FROM z) SELECT product_id,MIN(day) AS start_day,MAX(day) AS end_day,COUNT(*) AS days FROM g GROUP BY product_id,grp','Gaps and Islands|Consecutive dates')
H('Demand during Stockouts','Return product_id, day and sold_units for zero-stock snapshots on dates with completed sales of that product. Aggregate lines before joining; include only positive units.',"WITH demand AS(SELECT i.product_id,o.order_date,SUM(i.quantity) AS units FROM orders o JOIN items i ON i.order_id=o.id WHERE o.status='completed' GROUP BY i.product_id,o.order_date) SELECT s.product_id,s.day,d.units AS sold_units FROM stock s JOIN demand d ON d.product_id=s.product_id AND d.order_date=s.day WHERE s.units=0 AND d.units>0",'Complex joins|Business case studies')
H('Subtree Payroll','Return every employee id and subtree_payroll including their own known salary and every direct or indirect report’s known salary. NULL salaries contribute zero. Manager hierarchy is acyclic, depth below 50.','WITH RECURSIVE tree AS(SELECT id AS root,id AS person FROM employees UNION ALL SELECT tree.root,e.id FROM tree JOIN employees e ON e.manager_id=tree.person) SELECT tree.root AS id,SUM(COALESCE(e.salary,0)) AS subtree_payroll FROM tree JOIN employees e ON e.id=tree.person GROUP BY tree.root','Recursive CTEs|Hierarchical queries')
H('Project Median Employee Salary','Return project_id and median_salary over distinct assigned employees with non-NULL salaries. Even counts average the two middle salaries. Exclude projects without known salaries.','WITH a AS(SELECT DISTINCT project_id,employee_id FROM assignments),r AS(SELECT a.project_id,e.salary,ROW_NUMBER() OVER(PARTITION BY a.project_id ORDER BY e.salary,e.id) AS rn,COUNT(*) OVER(PARTITION BY a.project_id) AS n FROM a JOIN employees e ON e.id=a.employee_id WHERE e.salary IS NOT NULL) SELECT project_id,ROUND(AVG(salary),2) AS median_salary FROM r WHERE rn IN(FLOOR((n+1)/2.0),FLOOR((n+2)/2.0)) GROUP BY project_id','Percentiles and medians|Complex joins')
H('RFM Quartile Scores','As of 2025-03-15, for customers with completed orders up to that date return customer_id, r_score, f_score and m_score. Divide buyers into four NTILE buckets per metric: higher scores are better. Recency uses last purchase descending, frequency count descending, monetary sum descending. Break all metric ties by customer_id; score=5-bucket.',"WITH r AS(SELECT customer_id,MAX(order_date) AS last_date,COUNT(*) AS frequency,SUM(amount) AS monetary FROM orders WHERE status='completed' AND order_date<='2025-03-15' GROUP BY customer_id) SELECT customer_id,5-NTILE(4) OVER(ORDER BY last_date DESC,customer_id) AS r_score,5-NTILE(4) OVER(ORDER BY frequency DESC,customer_id) AS f_score,5-NTILE(4) OVER(ORDER BY monetary DESC,customer_id) AS m_score FROM r",'Customer segmentation|Window functions')
H('Balanced Merchant Concentration','For each account with positive debit spending and non-NULL merchants, return account_id, largest_merchant_share_pct and hhi. HHI is the sum of squared merchant spending fractions (0–1 scale). Round percentage to 2 decimals and HHI to 4.',"WITH m AS(SELECT account_id,merchant,SUM(amount) AS spent FROM ledger WHERE kind='debit' AND merchant IS NOT NULL GROUP BY account_id,merchant),s AS(SELECT *,SUM(spent) OVER(PARTITION BY account_id) AS total FROM m) SELECT account_id,ROUND(MAX(100.0*spent/total),2) AS largest_merchant_share_pct,ROUND(SUM((1.0*spent/total)*(1.0*spent/total)),4) AS hhi FROM s WHERE total>0 GROUP BY account_id",'Window functions|Business case studies')
H('Seven-Day Rolling Distinct Audience','For every observed event date return day and active_customers in that day and preceding six calendar days. Count each customer once across the whole window.','WITH a AS(SELECT DISTINCT customer_id,DAYKEY(event_time) AS day FROM events),d AS(SELECT DISTINCT day FROM a) SELECT d.day,COUNT(DISTINCT a.customer_id) AS active_customers FROM d JOIN a ON DIFFDAY(d.day,a.day) BETWEEN 0 AND 6 GROUP BY d.day','Retention|Date functions')
H('Day One and Day Seven Cohort Grid','Cohort by first activity calendar day. Return cohort_day, cohort_size, day1_users and day7_users, requiring activity exactly 1 and 7 days later. Include zero-retention cohorts.','WITH a AS(SELECT DISTINCT customer_id,DAYKEY(event_time) AS day FROM events),f AS(SELECT customer_id,MIN(day) AS first_day FROM a GROUP BY customer_id) SELECT f.first_day AS cohort_day,COUNT(*) AS cohort_size,SUM(CASE WHEN EXISTS(SELECT 1 FROM a WHERE a.customer_id=f.customer_id AND DIFFDAY(a.day,f.first_day)=1) THEN 1 ELSE 0 END) AS day1_users,SUM(CASE WHEN EXISTS(SELECT 1 FROM a WHERE a.customer_id=f.customer_id AND DIFFDAY(a.day,f.first_day)=7) THEN 1 ELSE 0 END) AS day7_users FROM f GROUP BY f.first_day','Cohort analysis|Conditional aggregation')
H('Category Champions in Multiple Markets','Using completed line revenue by customer and product category, rank customers within each category using DENSE_RANK descending. Return customer_id and champion_categories for customers tied for first in at least two categories.',"WITH r AS(SELECT o.customer_id,p.category,SUM(i.quantity*i.unit_price) AS revenue FROM orders o JOIN items i ON i.order_id=o.id JOIN products p ON p.id=i.product_id WHERE o.status='completed' GROUP BY o.customer_id,p.category),ranked AS(SELECT *,DENSE_RANK() OVER(PARTITION BY category ORDER BY revenue DESC) AS rk FROM r) SELECT customer_id,COUNT(*) AS champion_categories FROM ranked WHERE rk=1 GROUP BY customer_id HAVING COUNT(*)>=2",'DENSE_RANK|Complex joins')
H('First Customer Revenue Milestone','For each customer reaching at least 300 completed cumulative order amount, return customer_id, milestone_order_id and cumulative_revenue for the first crossing. Order purchases by order_date then id.',"WITH r AS(SELECT *,SUM(amount) OVER(PARTITION BY customer_id ORDER BY order_date,id ROWS UNBOUNDED PRECEDING) AS cumulative FROM orders WHERE status='completed'),p AS(SELECT *,ROW_NUMBER() OVER(PARTITION BY customer_id ORDER BY order_date,id) AS rn FROM r WHERE cumulative>=300) SELECT customer_id,id AS milestone_order_id,cumulative AS cumulative_revenue FROM p WHERE rn=1",'Running totals|ROW_NUMBER')
# Adversarial cases supply positive counterexamples for all advanced predicates.
EXTRA['orders'] += [[21,1,'2025-03-03','completed',1500],[22,1,'2025-02-20','completed',700],[23,10,'2025-03-10','pending',0]]
EXTRA['items'] += [[21,6,10,100],[21,3,50,10],[22,2,7,100]]
EXTRA['friendships'] += [[4,5,'2025-02-05']]
EXTRA['ratings'] += [[11,10,8,5,'2025-03-11']]
EXTRA['orders'] += [[24,8,'2025-03-10','completed',100]]
EXTRA['items'] += [[24,2,1,100]]
COMPANIES=['Google','Amazon','Microsoft','Meta','Apple','Netflix','Uber','Airbnb','LinkedIn','Walmart','Flipkart','Adobe','Accenture','Deloitte','JPMorgan Chase','Goldman Sachs','Deutsche Bank','PayPal','Salesforce','Swiggy','Zomato','Meesho','PhonePe']
MACROS={'DAYKEY','MONTHKEY','MONTHGAP','DIFFDAY','DIFFMIN','SHIFT','MIDNIGHT'}
def compile_sql(s,engine):
 while True:
  m=re.search(r'\b('+ '|'.join(MACROS)+r')\(',s)
  if not m:break
  start=m.end();depth=1;pos=start;quoted=False
  while pos<len(s) and depth:
   ch=s[pos]
   if ch=="'":quoted=not quoted
   if not quoted:
    if ch=='(':depth+=1
    if ch==')':depth-=1
   pos+=1
  inner=s[start:pos-1];parts=[];depth=0;quoted=False;last=0
  for j,ch in enumerate(inner):
   if ch=="'":quoted=not quoted
   if not quoted:
    if ch=='(':depth+=1
    if ch==')':depth-=1
    if ch==',' and depth==0:parts.append(inner[last:j]);last=j+1
  parts.append(inner[last:]);a=[compile_sql(x.strip(),engine) for x in parts];fn=m.group(1)
  if fn=='DAYKEY':v=f'CAST({a[0]} AS DATE)' if engine=='postgres' else f'DATE({a[0]})'
  elif fn=='MONTHKEY':v=f"TO_CHAR(CAST({a[0]} AS DATE),'YYYY-MM')" if engine=='postgres' else f"DATE_FORMAT({a[0]},'%Y-%m')" if engine=='mysql' else f"strftime('%Y-%m',{a[0]})"
  elif fn=='MONTHGAP':
   typ='SIGNED' if engine=='mysql' else 'INTEGER'
   def mi(x):return f'(CAST(SUBSTRING({x},1,4) AS {typ})*12+CAST(SUBSTRING({x},6,2) AS {typ}))'
   v=f'({mi(a[0])}-{mi(a[1])})'
  elif fn=='DIFFDAY':v=f'(CAST({a[0]} AS DATE)-CAST({a[1]} AS DATE))' if engine=='postgres' else f'DATEDIFF({a[0]},{a[1]})' if engine=='mysql' else f'CAST(julianday({a[0]})-julianday({a[1]}) AS INTEGER)'
  elif fn=='DIFFMIN':v=f'FLOOR(EXTRACT(EPOCH FROM (CAST({a[0]} AS TIMESTAMP)-CAST({a[1]} AS TIMESTAMP)))/60)' if engine=='postgres' else f'TIMESTAMPDIFF(MINUTE,{a[1]},{a[0]})' if engine=='mysql' else f'CAST((unixepoch({a[0]})-unixepoch({a[1]}))/60 AS INTEGER)'
  elif fn=='SHIFT':v=f'(CAST({a[0]} AS DATE)+({a[1]}))' if engine=='postgres' else f'DATE_ADD({a[0]},INTERVAL {a[1]} DAY)' if engine=='mysql' else f"DATE({a[0]},'{int(a[1]):+d} day')"
  elif fn=='MIDNIGHT':v=f'CAST({a[0]} AS TIMESTAMP)' if engine=='postgres' else f'CAST({a[0]} AS DATETIME)' if engine=='mysql' else f"({a[0]} || ' 00:00:00')"
  s=s[:m.start()]+v+s[pos:]
 if engine=='sqlite':s=re.sub(r"CAST\(('\d{4}-\d{2}-\d{2}') AS DATE\)",r'DATE(\1)',s)
 return s

def literal(v):return 'NULL' if v is None else str(v) if isinstance(v,(int,float)) else "'"+v.replace("'","''")+"'"
def schema(names):return '\n'.join(f'CREATE TABLE {n} ({TABLES[n][0]});' for n in names)
def setup(names,data):return '\n'.join('INSERT INTO '+n+' VALUES '+','.join('('+','.join(map(literal,row))+')' for row in data[n])+';' for n in names if data[n]) or 'SELECT 1;'
def colnames(n):return [c.strip().split()[0] for c in TABLES[n][0].split(',') if c.strip() and not re.match(r'^\d+\)',c.strip())]
def columns_from_schema(n):
 # Commas inside DECIMAL precision are not column separators.
 return [x.strip().split()[0] for x in re.split(r',(?![^()]*\))',TABLES[n][0])]
def build():
 assert collections.Counter(p['difficulty'] for p in PROBLEMS)=={'Easy':40,'Medium':110,'Hard':50}
 seen=set();bank=[];all_empty=[]
 base={k:v[1] for k,v in TABLES.items()};expanded={k:base[k]+EXTRA.get(k,[]) for k in TABLES};empty={k:base[k] if k in ['customers','products','employees','projects','couriers','accounts'] else [] for k in TABLES}
 datasets=[('sample',False,base),('ties-boundaries',True,expanded),('empty-facts',True,empty),('all-empty',True,{k:[] for k in TABLES})]
 for index,p in enumerate(PROBLEMS,1):
  ident=f'q{index:03d}';names=[n for n in TABLES if re.search(r'\b'+n+r'\b',p['sql'])];assert names,(ident,p['title'])
  sqls={e:compile_sql(p['sql'],e) for e in ['postgres','mysql','sqlite']}
  assert sqls['postgres'] not in seen,p['title'];seen.add(sqls['postgres'])
  tests=[];columns=[]
  for name,hidden,data in datasets:
   conn=sqlite3.connect(':memory:');conn.executescript(schema(names));conn.executescript(setup(names,data))
   try:cur=conn.execute(sqls['sqlite']);rows=[list(r) for r in cur.fetchall()];cols=[c[0] for c in cur.description]
   except Exception as e:raise RuntimeError(f'{ident} {p["title"]}: {e}\n{sqls["sqlite"]}') from e
   if len(rows)>1000:raise ValueError('Result exceeds limit')
   columns=cols;tests.append({'id':name,'hidden':hidden,'setup':{'postgres':setup(names,data),'mysql':setup(names,data)},'expected':{'columns':[],'rows':rows}});conn.close()
  if all(not t['expected']['rows'] for t in tests):all_empty.append(ident+' '+p['title'])
  ctypes=[]
  for i,c in enumerate(columns):
   vals=[r[i] for t in tests for r in t['expected']['rows'] if r[i] is not None]
   ty='number' if not vals or isinstance(vals[0],(int,float)) else 'date' if re.fullmatch(r'\d{4}-\d{2}-\d{2}',str(vals[0])) else 'text'
   ctypes.append({'name':c,'type':ty})
  for t in tests:t['expected']['columns']=ctypes
  guidance={
   'SELECT and WHERE':'Apply each row-level condition in WHERE, and project only the requested columns.',
   'Aggregate functions':'COUNT(*) counts rows; COUNT(column) skips NULL. SUM and AVG also ignore NULL, and SUM over an empty input is NULL unless COALESCE supplies zero.',
   'GROUP BY':'Group at the requested business grain before computing the totals; every selected non-aggregated field must belong to that grain.',
   'HAVING':'Use WHERE for individual rows and HAVING for conditions on a finished group.',
   'NULL handling':'Use IS NULL to test missing values and NULLIF to protect zero denominators; do not replace NULL with zero unless requested.',
   'LEFT joins':'Keep the required entity on the left and place filters on optional rows in the ON clause. A filter on the right table in WHERE can discard unmatched entities.',
   'RIGHT joins':'A RIGHT JOIN preserves the right-side catalogue. Count a non-NULL field from the optional side to avoid counting an unmatched row as an occurrence.',
   'INNER joins':'Join on entity identifiers and apply the task-specific filters before aggregating.',
   'Self joins':'Give each copy of the table a separate alias. Make direction and tie conditions explicit to avoid double-counting pairs.',
   'Anti-joins':'NOT EXISTS keeps a row only when the correlated lookup finds no matching row. It avoids the NULL trap of NOT IN.',
   'NOT EXISTS':'Test for the absence of a qualifying related row with a correlated NOT EXISTS predicate.',
   'EXISTS':'EXISTS checks whether a qualifying related row exists without multiplying the outer rows.',
   'Semi-joins':'Use EXISTS when related records only determine eligibility, so multiple matches do not duplicate the result.',
   'ROW_NUMBER':'Partition by the entity and use a complete deterministic ordering, including the stated ID tie-break. Filter the assigned row numbers in an outer query.',
   'DENSE_RANK':'DENSE_RANK gives equal measures the same rank without gaps; it preserves all tied winners.',
   'RANK':'RANK gives tied measures the same rank and leaves gaps after ties. Do not replace it with ROW_NUMBER when all ties must survive.',
   'LAG and LEAD':'Use LAG or LEAD inside the correct entity partition. The window ordering must include every specified tie-break; boundary rows naturally return NULL.',
   'Running totals':'Order the window explicitly and use a ROWS frame so each input row contributes once, even when dates or measures tie.',
   'Window frames':'A ROWS frame counts observations, not elapsed days. Aggregate to the required grain before applying the frame.',
   'Rolling averages':'Distinguish an observed-row window from a calendar window. Calendar windows need date-range conditions when days can be missing.',
   'Gaps and Islands':'Deduplicate the calendar grain, mark each gap with LAG, cumulatively sum the break markers, and aggregate each resulting island.',
   'Consecutive dates':'Remove repeated dates before testing adjacency. Compare calendar differences so missing dates cannot be mistaken for a streak.',
   'Sessionization':'LAG identifies the preceding timestamp. Mark session starts, then cumulatively sum those markers within each customer.',
   'Recursive CTEs':'The anchor selects the initial roots or date. The recursive term advances one step, and the hierarchy/date bound guarantees termination.',
   'Relational division':'Use a double NOT EXISTS: no required item may be missing from the candidate set. Handle the empty required set according to the task.',
   'Percentiles and medians':'Sort every qualifying observation without deduplicating ties. Combine ROW_NUMBER with the partition count to select the specified position or middle pair.',
   'Complex joins':'Aggregate independent one-to-many relationships separately before joining their summaries, or use EXISTS when only eligibility matters.',
   'Conditional aggregation':'Place the business condition inside CASE and aggregate that indicator or value at the final output grain.',
   'Cohort analysis':"Identify each entity's cohort once, then join its later activity to that cohort. Keep the population denominator separate from the activity numerator.",
   'Funnel analysis':"Follow the task's event-order and elapsed-time rules literally. A later event does not prove that an earlier required step occurred.",
   'Revenue analytics':'Apply eligibility rules before summing money, and protect zero denominators. Independent revenue and refund streams must not be multiplied by a raw join.',
   'Duplicate detection':'Define duplicates by the stated business key. Use deterministic ordering to identify which original record to retain.',
   'FIRST_VALUE and LAST_VALUE':"FIRST_VALUE and LAST_VALUE depend on their window frame. Use an explicitly unbounded frame when the whole partition's last value is required."
  }
  steps=list(dict.fromkeys(guidance[t] for t in p['topics'] if t in guidance))
  if not steps:steps=['Build the qualifying entity set first, then compute the requested metric at the stated output grain. Keep NULLs and denominator rules explicit.']
  sample=tests[0]['expected']['rows']
  example=' A visible output row is '+', '.join(str(k)+'='+str(v) for k,v in zip(columns,sample[0]))+'.' if sample else ' The visible dataset has no qualifying rows; a hidden dataset includes a positive case.'
  explanation=p['explain'] or (' '.join(steps[:2])+example)

  q={
   'id':ident, 'slug':re.sub('[^a-z0-9]+','-',p['title'].lower()).strip('-'),
   'title':p['title'], 'difficulty':p['difficulty'], 'topics':p['topics'],
   'companies':[p['company'] or COMPANIES[(index-1)%len(COMPANIES)]],
   'attribution':'Company-style simulation',
   'statement':p['task']+'\n\nReturn columns in this order: '+', '.join(columns)+'.',
   'explanation':explanation,
   'constraints':[
    'IDs declared PRIMARY KEY are unique. Foreign identifiers reference existing entities unless the task explicitly audits missing links.',
    'Amounts and durations are non-negative. NULL is distinct from zero or an empty string.',
    'Source row order is not guaranteed. The judge checks more than the visible dataset.',
    'Each (product_id, day) stock key and (day, channel) advertising key is unique; friendship edges are unique and stored once.'
   ],
   'edgeCases':['Empty input tables and missing related records.','Tied measures, repeated activity and multiple records for the same entity.','NULL values and dates exactly on inclusion boundaries.'],
   'hints':['Identify the required output grain before joining tables.','Consider '+', '.join(p['topics'])+'. Aggregate before joining independent one-to-many relationships.'],
   'minutes':{'Easy':8,'Medium':18,'Hard':30}[p['difficulty']], 'ordered':p['ordered'],
   'tolerance':0.0001 if any('ROUND' in sql for sql in sqls.values()) else 0,
   'schema':{e:schema(names) for e in ['postgres','mysql']},
   'solutions':{e:sqls[e] for e in ['postgres','mysql']},
   'tables':[{'name':n,'columns':columns_from_schema(n),'rows':base[n]} for n in names],
   'tests':tests
  }
  bank.append(q)
 path=ROOT/'content/questions.json';path.write_text(json.dumps(bank,indent=2,ensure_ascii=False)+'\n')
 print(f'Generated {len(bank)} questions, {sum(len(q["tests"]) for q in bank)} datasets. Offline fixture oracle: SQLite {sqlite3.sqlite_version}.')
 if all_empty:print('NEED POSITIVE DATASETS:\n'+'\n'.join(all_empty))
 # Independent Python checks for representative calculation and boundary oracles.
 assert bank[0]['tests'][0]['expected']['rows']==[[1,'Asha'],[4,'Diya']]
